const a=JSON.parse('{"workId":"cai-gen-tan","chapter":{"id":"cai-gen-tan_ch-4","workId":"cai-gen-tan","order":4,"title":"閒適","difficulty":3,"estimatedMinutes":54,"passageIds":["cai-gen-tan_ch-4_p-1","cai-gen-tan_ch-4_p-2","cai-gen-tan_ch-4_p-3","cai-gen-tan_ch-4_p-4","cai-gen-tan_ch-4_p-5","cai-gen-tan_ch-4_p-6","cai-gen-tan_ch-4_p-7","cai-gen-tan_ch-4_p-8","cai-gen-tan_ch-4_p-9","cai-gen-tan_ch-4_p-10","cai-gen-tan_ch-4_p-11","cai-gen-tan_ch-4_p-12","cai-gen-tan_ch-4_p-13","cai-gen-tan_ch-4_p-14","cai-gen-tan_ch-4_p-15","cai-gen-tan_ch-4_p-16","cai-gen-tan_ch-4_p-17","cai-gen-tan_ch-4_p-18","cai-gen-tan_ch-4_p-19","cai-gen-tan_ch-4_p-20","cai-gen-tan_ch-4_p-21","cai-gen-tan_ch-4_p-22","cai-gen-tan_ch-4_p-23","cai-gen-tan_ch-4_p-24","cai-gen-tan_ch-4_p-25","cai-gen-tan_ch-4_p-26","cai-gen-tan_ch-4_p-27","cai-gen-tan_ch-4_p-28","cai-gen-tan_ch-4_p-29","cai-gen-tan_ch-4_p-30","cai-gen-tan_ch-4_p-31","cai-gen-tan_ch-4_p-32","cai-gen-tan_ch-4_p-33","cai-gen-tan_ch-4_p-34","cai-gen-tan_ch-4_p-35","cai-gen-tan_ch-4_p-36","cai-gen-tan_ch-4_p-37","cai-gen-tan_ch-4_p-38","cai-gen-tan_ch-4_p-39","cai-gen-tan_ch-4_p-40","cai-gen-tan_ch-4_p-41","cai-gen-tan_ch-4_p-42","cai-gen-tan_ch-4_p-43","cai-gen-tan_ch-4_p-44","cai-gen-tan_ch-4_p-45","cai-gen-tan_ch-4_p-46","cai-gen-tan_ch-4_p-47","cai-gen-tan_ch-4_p-48","cai-gen-tan_ch-4_p-49","cai-gen-tan_ch-4_p-50","cai-gen-tan_ch-4_p-51","cai-gen-tan_ch-4_p-52","cai-gen-tan_ch-4_p-53","cai-gen-tan_ch-4_p-54","cai-gen-tan_ch-4_p-55","cai-gen-tan_ch-4_p-56","cai-gen-tan_ch-4_p-57","cai-gen-tan_ch-4_p-58","cai-gen-tan_ch-4_p-59","cai-gen-tan_ch-4_p-60","cai-gen-tan_ch-4_p-61","cai-gen-tan_ch-4_p-62","cai-gen-tan_ch-4_p-63","cai-gen-tan_ch-4_p-64","cai-gen-tan_ch-4_p-65","cai-gen-tan_ch-4_p-66","cai-gen-tan_ch-4_p-67","cai-gen-tan_ch-4_p-68","cai-gen-tan_ch-4_p-69","cai-gen-tan_ch-4_p-70","cai-gen-tan_ch-4_p-71","cai-gen-tan_ch-4_p-72","cai-gen-tan_ch-4_p-73"],"tags":["文學","處世","閒適"]},"passages":[{"id":"cai-gen-tan_ch-4_p-1","chapterId":"cai-gen-tan_ch-4","order":1,"canonicalText":"真廉無廉名，立名者正所以為貪；大巧無巧術，用術者乃所以為拙。","sentenceIds":["cai-gen-tan_ch-4_p-1_s-1","cai-gen-tan_ch-4_p-1_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"真正廉潔的人並不會刻意去追求廉潔的名聲，那些處心積慮想建立好名聲的人，其動機正是為了滿足貪圖名譽的私欲；真正巧妙的智慧並不依賴心機與手段，那些喜歡使用權謀手段的人，其行為反而暴露出他們內心的愚拙。","analysis":"【訓詁與名物】「廉」指清廉、不貪污。「廉名」指清廉的好名聲。「立名」指刻意建立名聲。「巧」指精妙的智慧與技巧。「巧術」指機巧的手段與心計。「拙」指愚笨、拙劣。\\\\n【章法與結構】此段為極其工整的排偶句法，「真廉」對「大巧」，「無廉名」對「無巧術」，「立名者正所以為貪」對「用術者乃所以為拙」。句型重複，語氣堅定，形成強烈的對比與諷刺意味。\\\\n【思想與義理】這段文字深受老子「大巧若拙」思想的影響。指出世間許多表面上的美好品德與才能，若摻雜了刻意造作與功利目的，便失去了其本真。真正的美德與智慧，是自然流露而不著痕跡的。刻意求名即是貪名，賣弄心機反成愚昧，這提醒人們修養應當返璞歸真，追求內在的誠信與本質。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-2","chapterId":"cai-gen-tan_ch-4","order":2,"canonicalText":"心體光明，暗室中有青天；念頭闇昧，白日下有厲鬼。","sentenceIds":["cai-gen-tan_ch-4_p-2_s-1","cai-gen-tan_ch-4_p-2_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果內心光明磊落，即使身處黑暗的密室之中，也如同面對著萬裏青天般坦蕩；如果心思陰暗邪惡，即使走在光天化日之下，也會因為心虛而覺得周遭有惡鬼作祟。","analysis":"【訓詁與名物】「心體」指人的內心本性。「光明」指坦蕩、沒有私心雜念。「暗室」指沒有光線的隱密之處。「青天」比喻晴朗明亮的天空，引申為胸懷開闊、光明正大。「念頭」指心中的想法。「闇昧」指陰暗、隱蔽、不可告人。「厲鬼」指兇惡的鬼怪，此處比喻心中的恐懼與不安。\\\\n【章法與結構】全段以兩句對偶構成：「心體光明」對「念頭闇昧」，「暗室中有青天」對「白日下有厲鬼」。利用「暗室」與「青天」、「白日」與「厲鬼」的強烈反差，營造出極具張力的畫面感，令人印象深刻。\\\\n【思想與義理】此段深刻描繪了人的心理狀態對其感受外界環境的影響，即所謂「境由心造」。君子坦蕩蕩，小人長慼慼；內心的光明與黑暗，決定了一個人是生活在坦然自在的天堂，還是充滿恐懼不安的地獄。強調修身首重正心誠意，唯有心地光明，才能超越外在環境的限制，獲得真正的自由與安寧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-3","chapterId":"cai-gen-tan_ch-4","order":3,"canonicalText":"人知名位為樂，不知無名無位之樂為最真；人知飢寒為憂，不知不飢不寒之憂為更甚。","sentenceIds":["cai-gen-tan_ch-4_p-3_s-1","cai-gen-tan_ch-4_p-3_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人們只知道擁有功名和權位是快樂的，卻不知道沒有名聲、沒有官位的平淡生活才是最真實的快樂；人們只知道挨餓受凍是憂慮的，卻不知道在衣食無憂之時，精神上的空虛與心靈的折磨才是更嚴重的憂患。","analysis":"【主題與背景】此段對比了世俗眼中的苦樂與精神層面的真苦樂。名利權位（名位）往往伴隨著紛爭與束縛，而「無名無位」的隱逸生活能讓人享有心靈的自由與純真；「不飢不寒」本是幸事，但飽暖之後若無精神寄託，產生的荒誕、空虛與道德迷失（不飢不寒之憂），其痛苦往往超越物質的匱乏。\\\\n【詞義與名物】這充滿了佛道的超脫與對生命本質的深層思考。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-4","chapterId":"cai-gen-tan_ch-4","order":4,"canonicalText":"為惡而畏人知，惡中猶有善路；為善而急人知，善處即是惡根。","sentenceIds":["cai-gen-tan_ch-4_p-4_s-1","cai-gen-tan_ch-4_p-4_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"做了壞事卻害怕被別人知道，說明這惡行中還保留著一條改過向善的生路；做了好事卻急於讓天下人皆知，這種行善的動機本身就是作惡與虛偽的根源。","analysis":"【主題與背景】此段論述善惡的心理動機與本質。作惡而知羞恥畏人知（畏人知），代表良知未泯，羞惡之心仍在，故有轉化向善的可能；而行善若只是為了追求虛名、獲取回報（急人知），這就將道德工具化，本質是私欲的膨脹，反容易滋生偽善與欺騙，故稱「善處即是惡根」。\\\\n【詞義與名物】這警示世人行善應出於真誠，反省應深入心底。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-5","chapterId":"cai-gen-tan_ch-4","order":5,"canonicalText":"天之機緘不測，抑而伸、伸而抑，皆是播弄英雄、顛倒豪傑處。君子只是逆來順受、居安思危，天亦無所用其伎倆矣。","sentenceIds":["cai-gen-tan_ch-4_p-5_s-1","cai-gen-tan_ch-4_p-5_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"上天的運作變化莫測，有時打壓人使其隨後伸張，有時又讓人得意隨後使其受挫，這些都是上天用來捉弄英雄、折磨豪傑的手段。君子面對逆境時能安然承受，處於順境時能居安思危，那麼上天也就無法施展其捉弄人的把戲了。","analysis":"【主題與背景】此段論及人與天命、命運的博弈智慧。「天之機緘」指命運的微妙變化。\\\\n【詞義與名物】英雄豪傑往往因氣盛而隨命運的起伏大喜大悲，被命運「播弄」；而君子洞悉「抑伸相循」的規律，在逆境中不怨天尤人（逆來順受），在順境中不驕奢淫逸（居安思危），保持心境的平和淡定，從而超越了命運的束縛，使外在命運無法動搖其內心。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-6","chapterId":"cai-gen-tan_ch-4","order":6,"canonicalText":"福不可徼，養喜神以為招福之本；禍不可避，去殺機以為遠禍之方。","sentenceIds":["cai-gen-tan_ch-4_p-6_s-1","cai-gen-tan_ch-4_p-6_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"幸福與好運是無法強求的，只有培養平和歡喜的心境，才是招來福氣的根本之道；災禍與厄運是難以完全躲避的，只有消除內心的怨恨與害人之意，才是遠離災禍的有效方法。","analysis":"【訓詁與名物】「徼」同「僥」，指僥倖求取、強求。「喜神」指歡喜、和悅的心神與態度。「本」即根本、基礎。「避」指逃避、躲避。「殺機」指怨恨、憤怒或殘害他人的惡念。「方」即方法、途徑。\\\\n【章法與結構】本段為對偶句，結構對稱嚴密：「福不可徼」對「禍不可避」，「養喜神」對「去殺機」，「以為招福之本」對「以為遠禍之方」。將求福與避禍的道理並列論述，條理分明。\\\\n【思想與義理】這段話傳達了中國傳統哲學中「禍福無門，惟人自召」的觀念。外在的禍福往往非人力所能完全掌控，但人可以掌控自己的心境與意念。保持和悅歡喜的心情，自然能吸引善緣與福報；戒除心中的戾氣與惡念，自然能減少衝突與災禍。這教導人們不應向外盲目祈求，而應向內反求諸己，以修心來改變命運。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-7","chapterId":"cai-gen-tan_ch-4","order":7,"canonicalText":"十語九中未必稱奇，一語不中，則愆尤駢集；十謀九成未必歸功，一謀不成則訾議叢興。君子所以寧默毋躁、寧拙毋巧。","sentenceIds":["cai-gen-tan_ch-4_p-7_s-1","cai-gen-tan_ch-4_p-7_s-2","cai-gen-tan_ch-4_p-7_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"說話十句中猜對了九句，人們未必會稱讚你神奇，但只要有一句沒說對，責備與罪過就會紛至沓來；策劃十個計謀成功了九個，人們未必會把功勞歸於你，但只要有一個計謀失敗，非議與指責就會鋪天蓋地而來。因此君子寧可保持沉默而不急躁發言，寧可表現得愚拙而不投機取巧。","analysis":"【主題與背景】此段道盡了世態炎涼與人性的苛求，指出了君子防身避禍的守默守拙之道。世人往往健忘於功勞而敏感於過失（愆尤駢集、訾議叢興），因此多言多謀反而容易暴露出破綻、招致禍端。\\\\n【詞義與名物】洪應明主張「寧默毋躁，寧拙毋巧」，並非教人無所作為，而是勸誡人們收斂鋒芒，在複雜的人際環境中保持謹慎與穩重。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-8","chapterId":"cai-gen-tan_ch-4","order":8,"canonicalText":"天地之氣，暖則生，寒則殺。故性氣清冷者，受享亦涼薄。惟氣和暖心之人，其福亦厚，其澤亦長。","sentenceIds":["cai-gen-tan_ch-4_p-8_s-1","cai-gen-tan_ch-4_p-8_s-2","cai-gen-tan_ch-4_p-8_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大自然的氣候，溫暖時就能使萬物生長，寒冷時就會使萬物凋零。因此，性情冷酷孤僻的人，他所能得到的福分享受也必然是淡薄的。只有那些氣質溫和、心地熱情的人，他們的福分才會深厚，所帶來的恩澤也才能夠長久。","analysis":"【訓詁與名物】「天地之氣」指大自然的節氣與運作規律。「生」指生長、滋長。「殺」指肅殺、凋零。「性氣」指人的性情與氣質。「清冷」指冷漠、孤僻、不近人情。「受享」指所受用的福報與享受。「涼薄」指淡薄、微薄。「氣和暖心」指性情溫和、心地溫暖慈善。「澤」指恩澤、影響力。\\\\n【章法與結構】首句以大自然的「暖生寒殺」為起興，引出人事之理。接著以「故...者...」與「惟...之人...」進行正反對比論證，將自然現象與人的性格福報緊密結合，邏輯清晰，說服力強。\\\\n【思想與義理】本段運用了天人合一的思想，將自然界的規律投射到人類的道德修養上。指出人的性情如同氣候，冷酷無情者如同嚴冬，難以與人建立深厚的連結，自然福薄；溫和慈愛者如同春風，能滋潤萬物、廣結善緣，因此福厚澤長。這勸誡世人應涵養溫和厚道的品性，以善意待人，方能成就圓滿的人生。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-9","chapterId":"cai-gen-tan_ch-4","order":9,"canonicalText":"天理路上甚寬，稍遊心胸中，便覺廣大宏朗；人慾路上甚窄，纔寄跡眼前，俱是荊棘泥塗。","sentenceIds":["cai-gen-tan_ch-4_p-9_s-1","cai-gen-tan_ch-4_p-9_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遵循天理的道路是非常寬敞的，只要稍微用心體會，就會覺得心胸無比寬廣豁亮；沉溺於人慾的道路是非常狹窄的，只要將身心寄託在眼前的私利上，路途就到處都是荊棘與泥濘。","analysis":"【主題與背景】此段對比了「天理」與「人慾」在人生體驗上的寬窄境界。天理是公正無私的，行於天理之路上，心無罣礙，自然感到天地開闊、精神爽朗；人慾則是自私狹隘的，一旦陷入對名利物慾的追逐中（寄跡眼前），心靈便會被得失計較所束縛，處處碰壁，如同行走在「荊棘泥塗」之中。\\\\n【詞義與名物】這告誡世人應提升精神境界，超脫物慾的枷鎖。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-10","chapterId":"cai-gen-tan_ch-4","order":10,"canonicalText":"一苦一樂相磨練，練極而成福者，其福始久：一疑一信相參勘，勘極而成知者，其知始真。","sentenceIds":["cai-gen-tan_ch-4_p-10_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在人生的道路上，經過一次次的痛苦與快樂相互交替磨鍊，當磨鍊到了極點而得來的幸福，這樣的幸福才能夠長久保持；在追求真理的過程中，經過一次次的懷疑與相信相互交錯印證，當印證到了極點而獲得的知識，這樣的知識才是最真實的。","analysis":"【訓詁與名物】\\\\n「磨練」指在艱苦的環境中鍛鍊心性；「極」指頂點、極致；「參勘」意為相互檢驗、對照印證；「知」指真知灼見或對事物本質的認識。全句中的「一……一……」句型表示事物的反覆交替與對立統一。\\\\n【章法與結構】\\\\n此段為典型的對偶句，上聯論「福」，下聯論「知」。「一苦一樂」對「一疑一信」，「相磨練」對「相參勘」，「練極而成福者」對「勘極而成知者」，「其福始久」對「其知始真」。結構嚴謹對稱，將人生修養中的兩種不同層面——情感際遇的磨鍊與理智認知的辯證，作了完美的結合與類比。\\\\n【思想與義理】\\\\n作者在這裡深刻闡述了辯證的發展觀。真正的幸福不是一帆風順的享樂，而是歷經苦樂交織的考驗後，內心所達到的平靜與滿足，這種幸福才具有厚度而不易失去。同樣地，真正的智慧與知識，不能僅靠盲目的迷信，必須經歷懷疑、探索、求證的反覆過程。這體現了儒家「困心衡慮，而後作」的修養論，以及在實踐中求真知的精神，告訴我們不可畏懼挫折與迷惘，因為它們正是通往永恆與真理的必經之路。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-11","chapterId":"cai-gen-tan_ch-4","order":11,"canonicalText":"地之穢者多生物，水之清者常無魚，故君子當存含垢納污之量，不可持好潔獨行之操。","sentenceIds":["cai-gen-tan_ch-4_p-11_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"肥沃汙穢的泥土往往能滋養出繁茂的萬物，而過於清澈的水流中常常沒有魚兒生存。所以，君子應當懷有包容缺點、忍辱負重的度量，而不可以抱持過分潔身自好、孤芳自賞的操守。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈閒適〉第 230 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「地之穢者多生物水之清者常無魚故君子當存含……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「地」、「之」、「穢」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-4_p-11）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-12","chapterId":"cai-gen-tan_ch-4","order":12,"canonicalText":"泛駕之馬可就馳驅，躍冶之金終歸型範。只一優遊不振，便終身無個進步。白沙雲：「為人多病未足羞，一生無病是吾憂。」真確實之論也。","sentenceIds":["cai-gen-tan_ch-4_p-12_s-1","cai-gen-tan_ch-4_p-12_s-2","cai-gen-tan_ch-4_p-12_s-3","cai-gen-tan_ch-4_p-12_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"性情烈而踢翻車子的野馬，經過馴服後可以奔馳千里；在熔爐中濺跳出來的金屬，經過鍛造後終究會被鑄造成器皿。只有那種終日懶散、精神萎靡不振的人，才會一輩子都沒有進步的希望。陳白沙曾說：「人有缺點與過失並不可恥，一生都沒犯過錯、沒有遭遇磨難才是我所憂慮的。」這真是至理名言。","analysis":"【主題與背景】此段論述志向與進取精神的重要性。「泛駕之馬」和「躍冶之金」比喻性格倔強或有缺點但精力充沛、有爆發力的人，這種人只要引導得當，終能成大器；而「優遊不振」（消極懶散）則是無可救藥的致命傷。\\\\n【詞義與名物】引用明代教育家陳白沙的話，旨在說明遭遇挫折、發現缺點是成長의 契機，最怕的是平庸無奇、不思進取。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-13","chapterId":"cai-gen-tan_ch-4","order":13,"canonicalText":"人只一念貪私，便銷剛為柔，塞智為昏，變恩為慘，染潔為污，壞了一生人品。故古人以不貪為寶，所以度越一世。","sentenceIds":["cai-gen-tan_ch-4_p-13_s-1","cai-gen-tan_ch-4_p-13_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人只要心中生起一絲貪婪與自私的念頭，便會將原本剛正的氣節消磨成軟弱，將原本聰明的智慧蒙蔽成昏庸，將原本的恩情變成殘酷的傷害，將原本純潔的操守染成污濁，徹底毀掉了一生的道德人品。所以古人將「不貪」當作最珍貴的寶物，也因此能夠超然地度過一生。","analysis":"【訓詁與名物】\\\\n「貪私」指貪求私利；「銷」為鎔化、消磨；「剛」指剛正不阿的骨氣；「塞」意為蒙蔽、堵塞；「昏」指昏庸糊塗；「慘」指殘忍、刻薄；「度越」意指超越世俗、平安度過。「以不貪為寶」典出《左傳·襄公十五年》宋人獻玉給子罕，子罕不受，說：「我以不貪為寶，爾以玉為寶，若以與我，皆喪寶也。」\\\\n【章法與結構】\\\\n本段採用先破後立的論述結構。前半段連用四個「變……為……」（銷剛為柔、塞智為昏、變恩為慘、染潔為污）的排比句，氣勢急促地鋪陳「貪私」帶來的毀滅性後果，將無形的惡念具象化為四種品格的墮落。後半段則筆鋒一轉，引出古人「以不貪為寶」的典故作結，正面點出保全人品的關鍵。\\\\n【思想與義理】\\\\n這是一段深具儒家倫理色彩的箴言。作者一針見血地指出，「貪私」是摧毀一切高尚品格的根源。人一旦有了私欲，便會因為患得患失而失去道德勇氣（銷剛為柔），因為利慾薰心而失去判斷力（塞智為昏），甚至為了利益而忘恩負義、同流合污。因此，修身的核心在於「戒貪」。只有克己復禮，保持內心的清廉無私，才能不被外物所牽絆，從而保全完美的人格，達到超然物外、度越一世的境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-14","chapterId":"cai-gen-tan_ch-4","order":14,"canonicalText":"耳目見聞為外賊，情慾意識為內賊，只是主人公惺惺不昧，獨坐中堂，賊便化為家人矣。","sentenceIds":["cai-gen-tan_ch-4_p-14_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"眼睛與耳朵所接觸外界的誘惑是外在的盜賊，內心的情慾與種種雜念是內在的盜賊。只要我們心中那個真正的自我（主人公）能保持清醒清明而不糊塗，泰然自若地主持大局，那麼內外的盜賊反而都會被感化，變成忠誠的家人了。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈閒適〉第 233 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「耳目見聞為外賊情慾意識為內賊只是主人公惺……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「耳」、「目」、「見」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-4_p-14）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-15","chapterId":"cai-gen-tan_ch-4","order":15,"canonicalText":"圖未就之功，不如保已成之業；悔既往之失，亦要防將來之非。","sentenceIds":["cai-gen-tan_ch-4_p-15_s-1","cai-gen-tan_ch-4_p-15_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"企圖去謀劃尚未實現的功業，不如好好保全已經取得的成果；懊悔過去所犯下的過失，更應當警惕防範未來可能出現的錯誤。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈閒適〉第 234 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「圖未就之功不如保已成之業悔既往之失亦要防……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「圖」、「未」、「就」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-4_p-15）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-16","chapterId":"cai-gen-tan_ch-4","order":16,"canonicalText":"氣象要高曠，而不可疏狂。心思要縝緘，而不可瑣屑。趣味要沖淡，而不可偏枯。操守要嚴明，而不可激烈。","sentenceIds":["cai-gen-tan_ch-4_p-16_s-1","cai-gen-tan_ch-4_p-16_s-2","cai-gen-tan_ch-4_p-16_s-3","cai-gen-tan_ch-4_p-16_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人的氣度應該要高遠開闊，但不能流於狂妄放縱；心思應該要縝密嚴謹，但不能變得繁瑣碎碎念；生活情趣應該要恬靜淡雅，但不能變得枯燥乏味；道德操守應該要嚴格分明，但不能表現得過於偏激猛烈。","analysis":"【訓詁與名物】\\\\n「氣象」指人的氣質與胸襟；「高曠」為高遠開闊；「疏狂」指放蕩不羈、不受約束；「縝緘」同縝密，指心思細緻周到；「瑣屑」指繁瑣細碎；「沖淡」指恬靜淡泊；「偏枯」原指草木枯萎，此喻生活單調無趣、缺乏生機；「嚴明」指嚴格而涇渭分明；「激烈」指性情偏激、行事極端。\\\\n【章法與結構】\\\\n全段由四組句式相同的排比句構成，每組皆為「……要……，而不可……」的句型，將正面的品格與容易流弊的缺點並舉。句法整齊劃一，音韻和諧，不僅強化了論述的力道，也在視覺與聽覺上呈現出高度的對稱美，便於讀者誦讀與記憶。\\\\n【思想與義理】\\\\n這段話深蘊儒家中庸之道的智慧。作者指出，培養優良的品格必須掌握好「度」，過猶不及都會產生流弊。高曠易變為疏狂，縝密易流為瑣屑，沖淡易成偏枯，嚴明易轉為激烈。因此，真正的修養是在兩極之間尋求平衡，既要追求高尚的境界，又要隨時警惕自己不走向極端。這種圓融、中正的處世哲學，教導人們在修身養性時，必須具備深刻的自我省察能力，方能臻於完美而不偏頗的化境。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-17","chapterId":"cai-gen-tan_ch-4","order":17,"canonicalText":"風來疏竹，風過而竹不留聲；鴈度寒潭，鴈去而潭不留影。故君子事來而心始現，事去而心隨空。","sentenceIds":["cai-gen-tan_ch-4_p-17_s-1","cai-gen-tan_ch-4_p-17_s-2","cai-gen-tan_ch-4_p-17_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"清風吹過稀疏的竹林，風停之後，竹林裡不會留下風的聲音；大雁飛過清冷的水潭，雁陣遠去之後，水面上不會留下大雁的影子。因此，有修養的君子在事情發生時，心思才會顯現出來去應對；事情過去之後，心境就隨之恢復到空明寧靜的狀態。","analysis":"【訓詁與名物】\\\\n「疏竹」指稀疏的竹林；「度」為飛過、越過；「寒潭」指清冷深邃的水潭；「心始現」指心智開始運作，展現出應對事物的能力；「心隨空」指心境隨之恢復空靈澄澈，不留執念。「空」為佛家用武，指心無掛礙的境界。\\\\n【章法與結構】\\\\n作者巧妙地運用了兩個極具畫意的美麗譬喻作為前導。「風過竹」與「鴈度潭」對仗工整，動靜結合，營造出一種空靈深邃的意境。在自然現象的鋪陳之後，以「故」字作結，自然而然地引出「事來心現，事去心空」的人生哲理。從自然到人事，由景入理，過渡無縫，渾然天成。\\\\n【思想與義理】\\\\n這段文字完美融合了禪宗的「無住生心」與莊子的「用心若鏡」思想。風與竹、雁與潭的互動，象徵著外在環境與內心世界的接觸。君子的心境應如竹林與寒潭，當外物（事件）來臨時，能夠敏銳地感應並妥善處理（事來而心始現）；但當事情結束後，就應該放下一切，不留戀、不執著，讓心靈回歸本初的清淨無為（事去而心隨空）。這教導我們在紛繁複雜的現實生活中，既要積極應對挑戰，又要保持內心的空靈自由，不被過往的煩惱所羈絆。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-18","chapterId":"cai-gen-tan_ch-4","order":18,"canonicalText":"清能有容，仁能善斷，明不傷察，直不過矯，是謂蜜餞不甜、海味不鹹，纔是懿德。","sentenceIds":["cai-gen-tan_ch-4_p-18_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"為人清廉純潔卻能包容他人的過失，心地仁慈卻能在關鍵時刻果斷決策，聰明睿智卻不過分苛求明察秋毫，性情剛直卻不過分矯枉過正，這就好像蜜餞喫起來不過於甜膩、海鮮喫起來不過於死鹹一樣，這才是最美好、最崇高的品德。","analysis":"【訓詁與名物】\\\\n「清」指清廉、高潔；「有容」指有度量包容他人；「仁」為仁愛之心；「善斷」指善於決斷；「明」指精明；「傷察」指因過於苛察而傷人和氣；「直」指剛直；「過矯」指矯枉過正，過度糾正；「蜜餞」指糖漬水果；「懿德」指美好、高尚的品德。\\\\n【章法與結構】\\\\n全段由四個「……能/不……」的對句組成，分別探討清與容、仁與斷、明與察、直與矯這四對德行的平衡。隨後，作者別出心裁地使用飲食中的「蜜餞不甜」、「海味不鹹」作為生動的比喻，將抽象的道德哲理具象化為日常的味覺體驗，最後以「纔是懿德」總結全文，收束有力。\\\\n【思想與義理】\\\\n此段文字深刻闡釋了儒家中庸思想與辯證統一的修養觀。單一的品德若發展到極致，往往會產生負面效應：過清則刻薄，過仁則優柔，過明則苛刻，過直則傷人。真正的美德在於「和而不同」與「恰如其分」。正如最好的蜜餞保有甜味卻不膩口，最好的海產帶有鹹味卻不齁人，完美的品格應當是清廉而寬容、仁慈而果決、聰明而厚道、正直而溫和。這提醒我們在修身立德時，必須兼顧性格的互補與平衡，避免走入極端，方能成就圓滿的人格境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-19","chapterId":"cai-gen-tan_ch-4","order":19,"canonicalText":"貧家凈掃地，貧女凈梳頭。景色雖不艷麗，氣度自是風雅。士君子當窮愁寥落，奈何輒自廢弛哉！","sentenceIds":["cai-gen-tan_ch-4_p-19_s-1","cai-gen-tan_ch-4_p-19_s-2","cai-gen-tan_ch-4_p-19_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"貧窮的人家把庭院打掃得乾乾淨淨，貧寒的女子把頭髮梳理得整整齊齊；雖然外在的景象並不華美艷麗，但內在的氣度自然透露出一種高潔風雅。有學問修養的君子在面對窮困愁苦、冷落寂寥的處境時，怎麼可以輕易地就放棄對自我的要求而變得頹廢鬆懈呢！","analysis":"【訓詁與名物】「貧家凈掃地，貧女凈梳頭」以平民生活為喻，強調在物資匱乏中保持整潔。「氣度」指人的氣質與風度，亦可用於形容環境所展現的格調。「風雅」原指《詩經》中的國風與大小雅，後引申為高尚、脫俗的品味。「窮愁」指窮困與憂愁。「寥落」意為冷清、寂寞。「輒」是動輒、就。「廢弛」意為荒廢、鬆懈，指放棄自身的品德修養。\\\\n【章法與結構】全段以物喻人，先用「貧家」與「貧女」作比興，勾勒出一幅樸素而整潔的畫面，帶出「不艷麗」卻「風雅」的意境；後半段由此及彼，點出正題，勉勵「士君子」在身處逆境時應當堅守節操。前後兩部分以小見大，類比貼切，語氣上從陳述轉為強烈的反問，極具感染力與說服力。\\\\n【思想與義理】此句生動體現了儒家「安貧樂道」與「君子固窮」的思想。真正的修養不取決於外在的物質條件與環境順逆，而在於內心的操守與自我約束。即使生活貧困、遭遇挫折，君子依然要保持高潔的志向與優雅的生活態度，絕不可因處境艱難而自甘墮落。這教導我們在任何困境中，都應保有生命的尊嚴與不屈的精神。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-20","chapterId":"cai-gen-tan_ch-4","order":20,"canonicalText":"閒中不放過，忙中有受用。靜中不落空，動中有受用。暗中不欺隱，明中有受用。","sentenceIds":["cai-gen-tan_ch-4_p-20_s-1","cai-gen-tan_ch-4_p-20_s-2","cai-gen-tan_ch-4_p-20_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在閒暇之時不輕易放縱自己虛度光陰，到了繁忙之際自然能夠從容應對而獲益良多；在平靜之時不讓心靈空虛迷惘而保持專注，到了行動之際自然能夠發揮作用而得心應手；在暗室獨處時不做欺瞞隱蔽的虧心事，到了光明正大之際自然能夠坦蕩無愧而受人敬重。","analysis":"【訓詁與名物】「閒中」指空閒、無事之時。「放過」意為放縱、懈怠，不加檢點。「受用」在此指獲得益處、發揮作用或感到從容舒適。「落空」指心神散亂、毫無著落與收穫。「暗中」指不為人知的獨處之時，相當於儒家所謂的「慎獨」之境。「欺隱」指欺瞞他人、隱藏自己的過失或惡行。\\\\n【章法與結構】本段採用了極度工整的排比與對偶句式，構成「閒/忙」、「靜/動」、「暗/明」三組相對的概念。每一組都遵循「在某種狀態下不如何，在另一種相反狀態下便能有受用」的邏輯結構。句式短促有力，節奏明快，層層遞進，將生活與修行的三個層面緊密串聯，說理透徹。\\\\n【思想與義理】這是一段關於修心與工夫論的精彩論述。作者強調修行不能只在表面的、外在的（忙、動、明）時候下功夫，更要在隱蔽的、內在的（閒、靜、暗）時候自我砥礪。只有在閒暇時累積實力，在靜默時涵養心性，在獨處時堅守道德底線（慎獨），才能在應付繁雜世事時遊刃幹餘，在公眾面前光明磊落。這提醒我們，真正的品格與能力，往往是在無人知曉的微小處與平凡中培養出來的。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-21","chapterId":"cai-gen-tan_ch-4","order":21,"canonicalText":"念頭起處，纔覺向欲路上去，便挽從理路上來。一起便覺，一覺便轉，此是轉禍為福、起死回生的關頭，切莫當面錯過。","sentenceIds":["cai-gen-tan_ch-4_p-21_s-1","cai-gen-tan_ch-4_p-21_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當內心剛有某種念頭萌生之時，只要察覺到這個念頭是朝著私欲的道路上發展，就必須立刻將它拉回到合乎天理的道路上來。惡念一升起就能夠立刻察覺，一察覺就能夠立刻轉變，這正是將災禍轉化為福報、讓心靈從沉淪中起死回生的關鍵時刻，千萬不要在眼前白白錯失了這個扭轉的機會。","analysis":"【訓詁與名物】「念頭起處」指思想、意識剛剛萌發的瞬間。「欲路」指貪婪、自私等各種世俗欲望的途徑。「理路」指合乎天理、道德規範與理性的道路。「挽」是拉回、挽救。「一起便覺，一覺便轉」是禪宗與理學中講究的修心法門，強調對自心動態的敏銳覺察與及時修正。「關頭」指關鍵時刻或轉折點。\\\\n【章法與結構】全段文字充滿動態感與緊迫感。前半部點出「欲路」與「理路」的對立，並用一個「挽」字帶出具體的修持方法；中段以「一起便覺，一覺便轉」八個字，短促有力地總結了修心的核心步驟，展現出高度的警覺性；結尾將這種修心工夫提升到「轉禍為福、起死回生」的高度，並以「切莫當面錯過」作結，語重心長，極具棒喝之效。\\\\n【思想與義理】此句融合理學的「存天理，滅人慾」與禪宗的「覺觀」思想。作者指出，人生的善惡禍福，往往取決於起心動唸的一瞬間。欲望的萌發是人之常情，但關鍵在於能否保有強大的「覺知力」，在惡念未成行動之前，及時懸崖勒馬，以理智戰勝私欲。這種對自心的嚴格觀照與瞬間轉化的能力，不僅是個人品德修養的核心，更是趨吉避兇、掌控自我命運的根本之道。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-22","chapterId":"cai-gen-tan_ch-4","order":22,"canonicalText":"天薄我以福，吾厚吾德以迓之；天勞我以形，吾逸吾心以補之；天扼我以遇，吾亨吾道以通之。天且奈我何哉！","sentenceIds":["cai-gen-tan_ch-4_p-22_s-1","cai-gen-tan_ch-4_p-22_s-2","cai-gen-tan_ch-4_p-22_s-3","cai-gen-tan_ch-4_p-22_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果上天刻薄我，不給我足夠的福分，我就加強修養自己的品德來迎接受命；如果上天勞苦我的肉體，我就讓自己的內心保持安逸清靜來彌補身軀的疲憊；如果上天在際遇上故意阻撓我，讓我深陷困境，我就擴充並通達我所堅守的大道來突破困局。只要我能如此，上天又能拿我怎麼樣呢！","analysis":"【訓詁與名物】「薄」指微薄、刻薄，作動詞用指減少。「厚」是豐厚，作動詞用指增加、加強。「迓」是迎接之意。「勞」指使之勞累。「形」即形體、肉身。「逸」指安逸、放鬆。「扼」原指掐住脖子，引申為阻礙、困厄。「遇」指遭遇、際遇。「亨」通「通」，指通達、順暢。「道」指人生的信念與真理。\\\\n【章法與結構】本段使用了氣勢磅礡的三疊排比句式：「天薄我以福...；天勞我以形...；天扼我以遇...」，將外部環境（天）的打壓與內在自我（吾）的抗爭形成強烈的對比。結構上皆為「天以某種逆境加諸於我，我便以某種內在修為去化解」，層層推進，最後以一句「天且奈我何哉」的反問作結，將全段的昂揚氣勢推向最高潮。\\\\n【思想與義理】這是一段展現極度強大主體性與抗爭精神的文字。作者認為，雖然外在的福分、身體的勞苦以及人生的際遇往往由「天命」所決定，非人力所能完全掌控，但人卻可以透過「修德」、「安心」與「明道」來超越環境的限制。這種不向命運低頭、將逆境視為自我提升之契機的積極態度，充分彰顯了儒家「人定勝天」、「修身以俟命」的剛健精神，鼓勵人們在面對困境時，要向內求取力量，做自己命運的主人。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-23","chapterId":"cai-gen-tan_ch-4","order":23,"canonicalText":"真士無心徼福，天即就無心處牖其衷；險人著意避禍，天即就著意中奪其魂。可見天之機權最神，人之智巧何益！","sentenceIds":["cai-gen-tan_ch-4_p-23_s-1","cai-gen-tan_ch-4_p-23_s-2","cai-gen-tan_ch-4_p-23_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"真正有修養的君子並沒有刻意去祈求福報，上天卻偏偏會在他這種無所求的純真境界中，開啟他的智慧與善心；陰險狡詐的小人總是處心積慮地想要逃避災禍，上天卻偏偏會在他這種刻意算計的過程中，奪走他的心魄與生機。由此可見，上天的機巧與權變是最為神妙難測的，人類那些自作聰明的智巧算計又有什麼用處呢！","analysis":"【訓詁與名物】「真士」指修養高深、保有真性情的人。「徼福」指祈求、求取福報。「牖」原指窗戶，作動詞用指開啟、啟迪。「衷」指內心、本心。「險人」指陰險狡詐、心術不正的人。「著意」意為刻意、處心積慮。「奪其魂」比喻使其喪失心智、遭受懲罰以致神魂顛倒。「機權」指機密與權變，形容造物主的法則。「智巧」指世俗自作聰明的心機與手腕。\\\\n【章法與結構】全段以正反對比的手法構成，「真士」與「險人」對比，「無心」與「著意」對比，「徼福」與「避禍」對比，「牖其衷」與「奪其魂」對比。通過這兩組截然不同的人物與結果的強烈對照，順理成章地引出最後的結論：「天之機權最神，人之智巧何益」。說理透徹，警醒意味濃厚。\\\\n【思想與義理】此段深受道家「無為而無不為」以及因果報應思想的影響。作者指出，世間的福禍並非可以透過機關算盡來求取或逃避的。真君子因為「無心」，順應自然，不貪求名利，反而能得到上天的眷顧與內心的澄明；小人則因為過度貪婪與恐懼，終日算計，結果反而聰明反被聰明誤，自取滅亡。這告訴我們，與其在世俗中玩弄智巧、患得患失，不如回歸真誠與坦蕩，順應天理大道，這才是人生真正的安身立命之本。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-24","chapterId":"cai-gen-tan_ch-4","order":24,"canonicalText":"聲妓晚景從良，一世之煙花無礙；貞婦白頭失守，半生之清苦俱非。語雲：「看人只看後半截」，真名言也。","sentenceIds":["cai-gen-tan_ch-4_p-24_s-1","cai-gen-tan_ch-4_p-24_s-2","cai-gen-tan_ch-4_p-24_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"歌妓在晚年的時候選擇改嫁從良，那麼她前半生的風塵生活也不妨礙她成為良家婦女；貞潔的婦女到了白髮晚年時卻失去了節操，那麼她前半生守節的清苦操守也就全部付諸東流。俗話說：「評定一個人，只要看他的後半生。」這真是至理名言。","analysis":"【主題與背景】此段論及了傳統道德評價中關於「晚節」與「善終」的深刻法則，強調堅持操守的重要性。\\\\n【訓詁與名物】「聲妓」指古代賣唱或賣身的女子；「從良」指妓女脫離風塵，嫁作良家婦女；「煙花」借指風月場所的墮落生活；「失守」指喪失了貞潔的操守；「俱非」指全部被否定、付諸東流。\\\\n【章法與結構】前半部以「聲妓從良」與「貞婦失守」兩個極端且充滿張力的社會案例進行對比，強調晚年結局對一生評價的顛覆性影響。後半部則引用俗語「看人只看後半截」進行總結，點明主旨。\\\\n【思想與義理】一個人前半生縱有污點，只要晚年能改過自新，仍可得到社會的包容與認可；反之，即便前半生積累了極高的清譽，若晚節不保，也會將一生的努力毀於一旦。這警示人們在生命的後半程更應如履薄冰，堅持操守，不可半途而廢。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-25","chapterId":"cai-gen-tan_ch-4","order":25,"canonicalText":"平民肯種德施惠，便是無位的卿相；仕夫徒貪權市寵，竟成有爵的乞人。","sentenceIds":["cai-gen-tan_ch-4_p-25_s-1","cai-gen-tan_ch-4_p-25_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"普通百姓如果願意積德行善、施惠於人，那他就是沒有官爵名位的卿相高官；達官貴人如果只知道貪圖權勢、買好求寵，那他最終只會成為擁有爵位的乞丐。","analysis":"【主題與背景】此段對比了精神財富與世俗名利的本質。平民雖無官位，但若「種德施惠」，其人格尊貴、受人敬仰，等同於高官（無位卿相）；官員雖有爵位，但若「貪權市寵」，其靈魂卑微、搖尾乞憐，與乞丐無異（有爵乞人）。\\\\n【詞義與名物】這繼承了孟子關於「天爵」（仁義忠信）與「人爵」（公卿大夫）的學說，強調精神道德的高尚才是真正的尊貴。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-26","chapterId":"cai-gen-tan_ch-4","order":26,"canonicalText":"問祖宗之德澤，吾身所享者是，當念其積累之難；問子孫之福祉，吾身所貽者是，要思其傾覆之易。","sentenceIds":["cai-gen-tan_ch-4_p-26_s-1","cai-gen-tan_ch-4_p-26_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"若要問祖宗留下了多少恩德與福澤，看看我們現在身上所享受的一切就知道了，因此應當常念他們當年積累這些福德的艱辛；若要問子孫未來能有多少福分，看看我們現在傳遞給他們什麼就知道了，因此必須時刻警惕這些家業敗亡覆滅的是多麼容易。","analysis":"【訓詁與名物】「德澤」指恩德與福澤。「貽」指遺留、傳給。「傾覆」指倒塌、敗亡、覆滅。\\\\n【章法與結構】本段以時間為軸，結構對仗嚴整。前半句回望過去（祖宗），由「果」（吾身所享）推導出對「因」（積累之難）的感恩；後半句展望未來（子孫），由現在的「因」（吾身所貽）警告未來的「果」（傾覆之易）。一承一啟，邏輯極為縝密。\\\\n【思想與義理】這段話蘊含了深厚的儒家家庭倫理與傳統的因果觀念。它提醒人們不要將現有的安逸視為理所當然，而應有飲水思源的感恩之心（念積累之難）；同時，更要有居安思危的憂患意識（思傾覆之易）。一個家族的興衰，往往就在於這承先啟後的一代人是否能夠守住道德底線並勤儉持家，這是一種極具歷史縱深感的生活哲學。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-27","chapterId":"cai-gen-tan_ch-4","order":27,"canonicalText":"君子而詐善，無異小人之肆惡；君子而改節，不若小人之自新。","sentenceIds":["cai-gen-tan_ch-4_p-27_s-1","cai-gen-tan_ch-4_p-27_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"君子如果偽裝善良，這與小人毫無顧忌地作惡沒有兩樣；君子如果改變節操、晚節不保，還不如小人改過自新、重新做人。","analysis":"【主題與背景】本段論述了「節操」的純粹性與偽善的危害。儒家思想極重誠意正心，君子若走上「詐善」之路，是以君子之名行欺世之實，其偽善對社會道德的破壞力甚至大於明目張膽作惡的小人。\\\\n【詞義與名物】而君子一旦在中途變節，背棄了平生所學所守，其墮落與堅守底線的失敗，反倒不如一個能痛改前非、洗心革面的小人來得真誠與可貴。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-28","chapterId":"cai-gen-tan_ch-4","order":28,"canonicalText":"家人有過不宜暴揚，不宜輕棄。此事難言，借他事而隱諷之。今日不悟，俟來日正警之。如春風之解凍、和氣之消冰，纔是家庭的型範。","sentenceIds":["cai-gen-tan_ch-4_p-28_s-1","cai-gen-tan_ch-4_p-28_s-2","cai-gen-tan_ch-4_p-28_s-3","cai-gen-tan_ch-4_p-28_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"家人如果犯了過錯，不應當粗暴地宣揚出去，也不應當輕易地嫌棄或放棄他們。如果事情難以直言，可以假借其他事情來委婉地暗示規勸；如果他們今天不能醒悟，就等待日後適當時機再正式警告提醒。要像春風吹解凍土、溫和的陽光消融冰雪那樣去感化家人，這才是經營家庭的典範與法則。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈閒適〉第 247 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「家人有過不宜暴揚不宜輕棄此事難言借他事而……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「家」、「人」、「有」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-4_p-28）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-29","chapterId":"cai-gen-tan_ch-4","order":29,"canonicalText":"此心常看得圓滿，天下自無缺陷之世界；此心常放得寬平，天下自無險側之人情。","sentenceIds":["cai-gen-tan_ch-4_p-29_s-1","cai-gen-tan_ch-4_p-29_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"只要把自己的內心常保圓滿無缺的狀態，那麼看天下自然就沒有什麼有缺陷的世界；只要把自己的內心常保寬廣平和的境界，那麼看天下自然就沒有什麼險惡偏狹的人情世故。","analysis":"【訓詁與名物】「圓滿」指完備、沒有缺失，在此引申為心胸開闊、不斤斤計較。「寬平」指寬宏平和。「險側」指險惡偏狹、陰險狡詐。\\\\n【章法與結構】本段為標準的對仗句型。上下兩句皆以「此心常...」開頭，提出內在修養的條件，接著以「天下自無...」作結，推導出外在世界的改變。這種從「心」到「世界」的邏輯推演，結構簡潔而意旨深遠。\\\\n【思想與義理】此段深刻體現了佛教唯識學與陽明心學中「境由心造」、「萬法唯心」的哲學思想。洪應明認為，外在世界的缺陷與人情的險惡，往往是源於我們內心的偏執與狹隘。如果能提升自己的心靈境界，以圓滿、寬平的心態去包容萬物，那麼外在的紛擾便無法動搖我們內在的平靜。這是一種高度的心理調適與精神超越。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-30","chapterId":"cai-gen-tan_ch-4","order":30,"canonicalText":"淡薄之士，必為濃艷者所疑；檢飭之人，多為放肆者所忌。君子處此固不可少變其操履，亦不可太露其鋒芒。","sentenceIds":["cai-gen-tan_ch-4_p-30_s-1","cai-gen-tan_ch-4_p-30_s-2","cai-gen-tan_ch-4_p-30_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"恬淡名利、生活清淡的隱逸之士，必定會被熱衷功名富貴的濃艷之人所懷疑；行為端正、約束檢點的嚴謹之人，大多會被放蕩不羈、肆無忌憚的人所嫉恨。君子處於這種境遇，固然不可以絲毫改變自己的操守與行為，但也絕不可以過分顯露自己的鋒芒。","analysis":"【主題與背景】此段探討了君子在世俗社會中的處世藝術。在清濁混雜的社會中，潔身自好者往往會因為與眾不同而招致世俗的猜忌與排擠。\\\\n【詞義與名物】作者給出的處世良方是「外圓內方」：一方面要堅守內在的道德操守（不可少變其操履），另一方面要收斂外在的鋒芒，避免過度表現清高以激怒世俗（不可太露其鋒芒），如此方能自我保護並推行道義。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-31","chapterId":"cai-gen-tan_ch-4","order":31,"canonicalText":"居逆境中，周身皆鍼砭藥石，砥節礪行而不覺；處順境內，滿前盡兵刃戈矛，銷膏糜骨而不知。","sentenceIds":["cai-gen-tan_ch-4_p-31_s-1","cai-gen-tan_ch-4_p-31_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"處在逆境之中，身邊的所有人事物都像是指責過錯、治病救命的針灸與良藥，在不知不覺中磨礪著自己的節操與品行；處在順境之中，眼前的一切都如同隱藏的兵刃與戈矛，在毫無防備中銷蝕著自己的骨肉與意志，自己卻渾然不覺。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈閒適〉第 250 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「居逆境中周身皆鍼砭藥石砥節礪行而不覺處順……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「居」、「逆」、「境」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-4_p-31）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-32","chapterId":"cai-gen-tan_ch-4","order":32,"canonicalText":"生長富貴叢中的，嗜慾如猛火、權勢似烈焰。若不帶些清冷氣味，其火焰不至焚人，必將自焚。","sentenceIds":["cai-gen-tan_ch-4_p-32_s-1","cai-gen-tan_ch-4_p-32_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"生長在富貴之家的人，他們的嗜好與慾望如同猛火，手中的權力與勢力好似烈焰。如果不能帶有一點清心寡慾、冷靜淡泊的氣息，這股熊熊烈火即便不至於去燒傷別人，也必定會將自己焚燒殆盡。","analysis":"【主題與背景】這是一則專對富貴子弟發言的箴言，警告富貴與權勢極易放大人的私欲與傲慢，導致自我毀滅。\\\\n【訓詁與名物】「富貴叢中」指生長在極度富裕與權勢顯赫的家族環境中；「嗜慾」指對物質與感官享受的強烈渴望；「清冷氣味」指清心寡慾、冷靜淡泊的理智與胸懷；「自焚」比喻因放縱欲望與濫用權力而招致自我毀滅。\\\\n【章法與結構】先以「猛火」與「烈焰」為喻，生動描繪出富貴環境中極易膨脹的欲望與權力狂熱；接著以「若不...必將...」的假設句式提出警告，點出缺乏理智節制的致命後果。\\\\n【思想與義理】富貴與權勢本身並非罪惡，但身處順境與高位者，最需要的是注入「清冷」的智慧——即自我剋制、保持清醒與悲憫之心。若任由欲望與權力如烈火般燃燒，最終必然是害人害己、引火自焚。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-33","chapterId":"cai-gen-tan_ch-4","order":33,"canonicalText":"人心一真，便霜可飛、城可隕、金石可貫。若偽妄之人，形骸徒具，真宰已亡。對人則面目可憎，獨居則形影自愧。","sentenceIds":["cai-gen-tan_ch-4_p-33_s-1","cai-gen-tan_ch-4_p-33_s-2","cai-gen-tan_ch-4_p-33_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人的內心一旦有了真誠，便能感動上天讓夏日飛霜，能讓堅固的城牆倒塌，也能貫穿堅硬的金屬與石頭。如果是虛偽狂妄的人，就只是空有一副肉體軀殼，內在真實的主宰早已消亡。這種人面對別人時會讓人覺得面目可憎，獨處時也會對著自己的形體和影子感到羞愧。","analysis":"【訓詁與名物】「霜可飛」典出鄒衍受冤而六月飛霜。「城可隕」典出杞梁妻哭崩齊長城。「金石可貫」典出熊渠子射虎，箭矢射入石頭中。這三個典故皆比喻精誠所至，金石為開。「真宰」源自《莊子》，指主宰生命的精神與真性。「面目可憎」指相貌神情令人厭惡。\\\\n【章法與結構】本段採用強烈的正反對比手法。前半段連用三個古代典故，極力鋪陳「真誠」的巨大力量，氣勢磅礴；後半段則筆鋒一轉，描繪「偽妄之人」外強中乾的醜態，從與人交往的「面目可憎」到獨處時的「形影自愧」，層層剝開虛偽者的可悲。\\\\n【思想與義理】這段話融合了儒家「誠」的修養哲學與道家「真宰」的生命觀。作者極度推崇「真誠」，認為它是天地間最強大的精神力量，能超越物理法則（飛霜、隕城、貫石）。反之，失去真誠的虛偽者，其生命便失去了靈魂（真宰已亡），不僅無法獲得他人的尊重，最終也無法面對自己的良知。這是對道德純粹性的最高禮讚。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-34","chapterId":"cai-gen-tan_ch-4","order":34,"canonicalText":"文章做到極處，無有他奇，只是恰好；人品做到極處，無有他異，只是本然。","sentenceIds":["cai-gen-tan_ch-4_p-34_s-1","cai-gen-tan_ch-4_p-34_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"文章寫到最高的境界，並沒有什麼奇特巧妙之處，只是表達得恰到好處；人品修養達到最高的境界，也沒有什麼奇特怪異之處，只是回歸到人性的本真自然。","analysis":"【主題與背景】本段揭示了文學創作與人格修養的最高境界——「大巧若拙，大雅若俗」。極致的文章不靠辭藻的堆砌或奇特的結構，而在於自然、精準地表達思想感情，達到「恰好」；最高尚的人格並非刻意追求標新立異的奇行，而是洗盡鉛華，回歸本性的純真與自然（本然）。\\\\n【詞義與名物】這體現了道家「返璞歸真」與儒家「中庸」的融合。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-35","chapterId":"cai-gen-tan_ch-4","order":35,"canonicalText":"以幻跡言，無論功名富貴，即肢體亦屬委形；以真境言，無論父母兄弟，即萬物皆吾一體。人能看的破，認的真，纔可以任天下之負擔，亦可脫世間之韁鎖。","sentenceIds":["cai-gen-tan_ch-4_p-35_s-1","cai-gen-tan_ch-4_p-35_s-2","cai-gen-tan_ch-4_p-35_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果從虛幻無常的表象來看，不論是功名利祿還是富貴榮華，甚至連我們自己的身軀肢體，都只不過是自然暫時寄託的形體而已；如果從真實永恆的境界來看，不論是父母兄弟等至親，甚至連天地間的萬事萬物，都與我同屬於一個整體的生命。人如果能夠看破世俗的虛幻，認清宇宙的真理，才能夠承擔起拯救天下的重責大任，同時也能夠擺脫世俗名利的羈絆與枷鎖。","analysis":"【訓詁與名物】「幻跡」指虛幻不實的表象或事物；「委形」語出《莊子》，意為大自然暫時委託寄放的形體。「真境」指宇宙人生的真實本體與境界；「吾一體」指萬物與我同根同源，不可分割。「看的破」指洞察表象的虛幻；「認的真」指體認到本體的真實；「韁鎖」比喻束縛人的名利與世俗觀念。\\\\n【章法與結構】本段採正反兩面的論述方式。「以幻跡言」與「以真境言」構成強烈的對比。前者破除世人對功名與肉身的執著，後者建立起對宇宙萬物的大愛。最後一句「人能...」則將這兩種境界統一於一身，既能入世擔當，又能出世解脫，邏輯嚴密，境界闊大。\\\\n【思想與義理】此句融合了莊子的齊物論與儒家的萬物一體之仁。在道家看來，有形之物皆是虛幻與暫時的，不應過分執著，這是「看的破」；在儒家與理學看來，人與萬物在精神上是相通的，必須具備同體大悲的胸懷，這是「認的真」。唯有具備這種超越的智慧與宏大的悲憫，人才能在承擔天下重任時不被世俗的名韁利鎖所困。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-36","chapterId":"cai-gen-tan_ch-4","order":36,"canonicalText":"爽口之味，皆爛腸腐骨之藥，五分便無殃；快心之事，悉敗身散德之媒，五分便無悔。","sentenceIds":["cai-gen-tan_ch-4_p-36_s-1","cai-gen-tan_ch-4_p-36_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"那些令人喫起來覺得美味可口的食物，往往都是會導致腸胃潰爛、骨骼腐敗的毒藥，只要喫到五分飽就不會帶來災禍；那些令人做起來覺得痛快淋漓的事情，往往都是導致身體敗壞、道德喪失的媒介，只要做到五分程度就懂得適可而止，便不會產生後悔。","analysis":"【訓詁與名物】「爽口之味」指美味的飲食；「爛腸腐骨之藥」形容飲食過度對身體的極大傷害。「五分」指一半的程度，代表適可而止。「快心之事」指能極大滿足個人欲望或情緒的事情；「敗身散德」指敗壞身體健康與散失道德修養；「媒」指媒介、導火線。\\\\n【章法與結構】全段以極具震撼力的誇飾手法構成對偶。「爽口之味」對應「快心之事」，皆是世人所追求的；「爛腸腐骨之藥」對應「敗身散德之媒」，則揭示其潛在的危險。最後皆以「五分便無...」作結，提出了極具操作性的解決方案。語氣警拔，令人深省。\\\\n【思想與義理】這段話蘊含了老莊哲學中「五色令人目盲，五味令人口爽」的養生與戒欲思想。世間的極致享受，背後往往隱藏著毀滅性的危機。因此，無論是口腹之慾還是精神上的狂歡，都不能過度放縱。作者提出了「五分」的節制哲學，告誡人們在面對誘惑時要懂得「知止」，唯有保持適度，才能保全性命與品德。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-37","chapterId":"cai-gen-tan_ch-4","order":37,"canonicalText":"不責人小過，不發人陰私，不念人舊惡，三者可以養德，亦可以遠害。","sentenceIds":["cai-gen-tan_ch-4_p-37_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不去苛責別人犯下的微小過失，不去揭發別人隱藏的私密短處，不去記恨別人過去曾經犯下的罪惡，做到這三點，不僅可以培養自己寬宏的道德修養，也可以讓自己遠離他人報復的禍害。","analysis":"【訓詁與名物】「小過」指微小的錯誤或無心之失；「陰私」指他人不願公開的隱私、短處或見不得光的事情；「舊惡」指他人過去曾犯的過錯或與自己結下的舊怨。「養德」指涵養自身的道德品格；「遠害」指遠離禍害，避免樹敵。\\\\n【章法與結構】這是一段典型的排比句法。「不責...」、「不發...」、「不念...」三個「不」字句並列，涵蓋了待人接物的三個重要面向：寬容當下的過失、尊重他人的隱私、釋懷過去的恩怨。最後以「三者...」進行總結，指出這三項原則兼具內修與外保的雙重功效，條理清晰，言簡意賅。\\\\n【思想與義理】此句體現了儒家「恕道」的實踐原則。《論語》雲「伯夷、叔齊不念舊惡，怨是用希」，寬恕不僅是美德，更是處世的智慧。喜歡挑剔別人的小錯、揭人隱私或記仇，必定會招致別人的怨恨與報復。因此，寬容待人看似在保護別人，實則是為了涵養自己的心性，並為自己創造一個安全和諧的人際環境。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-38","chapterId":"cai-gen-tan_ch-4","order":38,"canonicalText":"天地有萬古，此身不再得；人生只百年，此日最易過。幸生其間者，不可不知有生之樂，亦不可不懷虛生之憂。","sentenceIds":["cai-gen-tan_ch-4_p-38_s-1","cai-gen-tan_ch-4_p-38_s-2","cai-gen-tan_ch-4_p-38_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"天地宇宙的存在是萬古長存的，但我們這個肉身生命一旦失去就再也無法重新獲得；人的一生充其量不過短短百年，而眼前的每一天都是最容易匆匆流逝的。有幸生活在這天地之間的人，不可以不懂得享受生命的樂趣，同時也不可以不心懷虛度光陰的憂慮。","analysis":"【訓詁與名物】「萬古」指極為久遠的時間，代表永恆；「不再得」指生命不可逆，死後無法復生。「百年」為古人對人類壽命極限的概稱；「最易過」感嘆時光飛逝。「有生之樂」指活著所能體驗到的各種美好與意義；「虛生」指虛度一生，沒有任何建樹或修養；「憂」指警惕與憂慮。\\\\n【章法與結構】本段前四句以兩組對比構成：「天地有萬古」與「此身不再得」對比了宇宙的永恆與個人生命的短暫；「人生只百年」與「此日最易過」則進一步強調時間的侷促與流逝的無情。結尾則以「不可不...亦不可不...」的雙重否定句式，提出了面對短暫人生應有的兩種積極態度。\\\\n【思想與義理】此段文字充滿了對生命存在意義的深沉哲思。一方面，作者肯定了生命的珍貴與美好，鼓勵人們去體會「有生之樂」，這有別於佛教的完全出世觀；另一方面，作者又帶有強烈的儒家入世精神與時間焦慮，警告人們切勿浪費光陰。這種既熱愛生活又戒慎恐懼的態度，鼓勵人們在有限的時間內創造無限的價值，活出充實的人生。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-39","chapterId":"cai-gen-tan_ch-4","order":39,"canonicalText":"老來疾病都是壯時招得；衰時罪孽都是盛時作得。故持盈履滿，君子尤兢兢焉。","sentenceIds":["cai-gen-tan_ch-4_p-39_s-1","cai-gen-tan_ch-4_p-39_s-2","cai-gen-tan_ch-4_p-39_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人到老年時所承受的各種疾病，往往都是在年輕力壯時不懂得愛惜身體而招惹來的；人到衰敗時所面臨的各種罪責與災禍，往往都是在運勢強盛時驕縱妄為所種下的惡果。因此，在處於圓滿鼎盛的狀態時，君子會特別保持小心謹慎的態度，不敢有絲毫懈怠。","analysis":"【訓詁與名物】「壯時」指年輕力壯的時期；「招」為招惹、引發。「衰時」指運勢衰落或年老體衰之時；「罪孽」指罪惡、災禍；「盛時」指勢力強大、運氣極佳的時期。「持盈履滿」指處於富貴極盛的境地（盈、滿皆指達到極點）；「兢兢」指小心謹慎、戒懼的樣子，語出《詩經》「戰戰兢兢」。\\\\n【章法與結構】前半段透過兩個對仗句「老來疾病...」與「衰時罪孽...」，揭示了時間上的因果報應關係。以「壯/老」、「盛/衰」的對比，點出人在順境與逆境中的強烈落差。後半段「故持盈...」則是結論，由前面的現象推導出君子應有的修養與作法，邏輯推演自然順暢。\\\\n【思想與義理】這段話蘊含了深邃的道家辯證法與佛家因果論。世事往往盛極而衰，人在年輕氣盛或大權在握時，最容易驕傲自滿、放縱欲望，這些不知節制的行為，便是日後病痛與災禍的種子。因此，真正的智者會在「盈滿」之時，心懷憂患，保持謙卑與剋制（即「持盈保泰」），唯有如此，才能避免未來的傾覆與悲劇。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-40","chapterId":"cai-gen-tan_ch-4","order":40,"canonicalText":"市私恩不如扶公議，結新知不如敦舊好，立榮名不如種陰得，尚奇節不如謹庸行。","sentenceIds":["cai-gen-tan_ch-4_p-40_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"與其施予私人的小恩惠來攏絡人心，不如維護社會的公理與正義；與其結交新的朋友，不如厚待與維繫舊有的情誼；與其建立表面榮耀的名聲，不如在暗中多積陰德；與其崇尚標新立異的奇特節操，不如在日常生活中謹慎自己的平庸行為。","analysis":"【訓詁與名物】「市」有買賣、籠絡之意。「私恩」指私人的恩惠。「扶」指支持、維護。「公議」即眾人公認的道理與正義。「敦」為敦厚、重視。「舊好」指老朋友。「陰得」即陰德，指不為人知的善行。「尚」指崇尚。「奇節」指異於常人的特殊節操。「庸行」指日常平凡的行為。\\\\n【章法與結構】本段為一組排比與對偶句，連續使用了四個「...不如...」的句型。「市私恩」對「結新知」、「立榮名」、「尚奇節」，「扶公議」對「敦舊好」、「種陰得」、「謹庸行」，句式齊整，層層遞進，將「捨本逐末」的世態與「返璞歸真」的修養進行了強烈的對比。\\\\n【思想與義理】這段文字探討了為人處世的本末之道。作者批判了世人往往喜歡追求表面的名聲、短暫的利益與特異的行為，而忽略了公平正義、長久情誼、隱密善行與日常道德的培養。真正的修養與德行，往往體現在平凡、平淡與不求人知的累積之中，這才是最堅實可靠的人生根基。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-41","chapterId":"cai-gen-tan_ch-4","order":41,"canonicalText":"公平正論不可犯手，一犯手則遺羞萬世；權門私竇不可著腳，一著腳則玷污終身。","sentenceIds":["cai-gen-tan_ch-4_p-41_s-1","cai-gen-tan_ch-4_p-41_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"關於公平正義的言論與準則絕不可以去觸犯或破壞，一旦觸犯了，就會留下千秋萬世的羞辱；權貴勢力與私相授受的門路絕不可以去涉足，一旦涉足其中，就會玷污自己一生的清白。","analysis":"【訓詁與名物】「公平正論」指公正的道理與正確的輿論。「犯手」指動手幹預、觸犯或破壞。「遺羞萬世」指留下萬代的恥辱。「權門」指有權勢的人家或集團。「私竇」指私下鑽營的門路、見不得人的漏洞。「著腳」指踏入、涉足。「玷污」指弄髒、使名譽受損。\\\\n【章法與結構】此段以兩組工整的對仗句構成。「公平正論」對「權門私竇」，「不可犯手」對「不可著腳」，「一犯手則遺羞萬世」對「一著腳則玷污終身」。句法嚴密，語氣峻厲，帶有強烈的警告意味。\\\\n【思想與義理】本段強調君子在面對大是大非時應有的堅定立場。公理正義是社會的底線，權力慾望是腐敗的深淵。作者警告世人，在關鍵時刻必須守住道德底線，不可為了私利而去挑戰公理或依附權貴，否則一步踏錯，便會造成無法挽回的身敗名裂。這是儒家氣節與風骨的深刻體現。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-42","chapterId":"cai-gen-tan_ch-4","order":42,"canonicalText":"曲意而使人喜，不若直節而使人忌；無善而致人譽，不如無惡而致人毀。","sentenceIds":["cai-gen-tan_ch-4_p-42_s-1","cai-gen-tan_ch-4_p-42_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"委屈自己的意志去迎合別人以討人歡心，不如保持正直的節操而遭到別人的忌憚；沒有真實的善行卻獲得別人的讚譽，不如沒有做過惡事卻遭到別人的毀謗。","analysis":"【訓詁與名物】「曲意」指委屈自己的本意去迎合他人。「直節」指剛直的節操。「忌」指忌諱、猜忌、顧忌。「致」指引來、獲得。「譽」指稱讚。「毀」指毀謗。\\\\n【章法與結構】全段以「...而...，不若...而...；...而...，不如...而...」的雙重對偶與對比句式組成。將「曲意」與「直節」、「無善受譽」與「無惡受毀」進行了強烈的價值觀碰撞，結構緊湊，發人深省。\\\\n【思想與義理】此段探討了名實與毀譽的真諦。在人際交往與社會評價中，世人往往容易迷失於追求他人的認同與讚美。然而作者認為，真實的品德遠比虛假的名聲更為重要。寧可因為堅持正道而被排擠，也不可為了討好而失去自我；寧可清白受屈，也不可虛偽受名。這展現了君子獨立不阿、求真求實的崇高人格。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-43","chapterId":"cai-gen-tan_ch-4","order":43,"canonicalText":"處父兄骨肉之變，宜從容不宜激烈；遇朋友交遊之失，宜剴切不宜優遊。","sentenceIds":["cai-gen-tan_ch-4_p-43_s-1","cai-gen-tan_ch-4_p-43_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"處理父兄等骨肉至親之間發生的變故或衝突時，應當態度從容溫和，不應當情緒激烈；面對朋友在交往中所犯的過錯與失誤時，應當真誠而懇切地指出規勸，不應當敷衍隨便、放任管教。","analysis":"【主題與背景】本段探討了親情與友情在處理矛盾時的不同原則。\\\\n【詞義與名物】家庭成員之間有著天然的血緣紐帶，處理矛盾應以愛與和睦為先，因此需要「從容」以避免傷害親情；而朋友之間的交往則建立在道義與志同道合的基礎上，當朋友犯錯時，必須「剴切」（真誠懇切地規勸）以幫助其改過，這才是真正的諍友之道。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-44","chapterId":"cai-gen-tan_ch-4","order":44,"canonicalText":"小處不滲漏，暗處不欺隱，末路不怠荒，纔是真正英雄。","sentenceIds":["cai-gen-tan_ch-4_p-44_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在細微的地方也不會疏忽遺漏，在別人看不見的暗處也不會自欺欺人或隱瞞作惡，在處境艱難的末路時也不會懈怠荒廢，這樣的人才是真正的英雄。","analysis":"【訓詁與名物】「小處」指微小的事情或細節。「滲漏」比喻疏忽、出差錯。「暗處」指沒有人看見的隱蔽地方。「欺隱」指欺瞞、隱藏過錯。「末路」指窮困潦倒或面臨絕境的時候。「怠荒」指懈怠、荒廢、放棄努力。\\\\n【章法與結構】本段採用三個「...處（路）不...」的排比句型疊加，層層遞進地描繪出英雄人物的特質，最後以「纔是真正英雄」作結，氣勢連貫，語氣鏗鏘有力。\\\\n【思想與義理】這段話打破了世俗對「英雄」僅僅是建立豐功偉業的刻板印象。作者指出，真正的英雄氣概體現在對自我的嚴格要求上：在細節處能謹慎，在獨處時能慎獨，在逆境中能堅韌。這種能夠戰勝自我怠惰、虛偽與懦弱的內在力量，才是最難能可貴、最真實的英雄本色。這與儒家「慎獨」與「歲寒然後知松柏之後凋」的修養功夫一脈相承。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-45","chapterId":"cai-gen-tan_ch-4","order":45,"canonicalText":"驚奇喜異者，終無遠大之識；苦節獨行者，要有恆久之操。","sentenceIds":["cai-gen-tan_ch-4_p-45_s-1","cai-gen-tan_ch-4_p-45_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"喜歡追求驚險奇特、標新立異的人，終究不會有長遠廣大的見識；過著刻苦節儉、特立獨行生活的人，必須要有能夠持之以恆的節操與毅力。","analysis":"【訓詁與名物】「驚奇喜異」指喜歡追求刺激、驚險、奇特或與眾不同的事物。「識」指見識、眼光。「苦節」指清苦的節操。「獨行」指特立獨行，不隨波逐流。「恆久」指長久堅持。「操」指操守、志向。\\\\n【章法與結構】這是一組對偶句，以「驚奇喜異者」對比「苦節獨行者」，並以「終無遠大之識」與「要有恆久之操」作為各自的評斷與期許。前句為否定與批評，後句為肯定與勉勵，語意一反一正，相映成趣。\\\\n【思想與義理】此段論述了性格與見識、修養的關係。追求奇異往往是出於浮躁與虛榮，這種人只看重表面的炫目，缺乏沉穩深厚的智慧，因此難成大器。相反地，能夠堅持苦節與獨行的人，雖然值得敬佩，但若是出於一時的衝動或矯情，也無法長久。因此，作者強調真正的修養不在於一時的特異，而在於能夠經得起時間考驗的平淡與堅持。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-46","chapterId":"cai-gen-tan_ch-4","order":46,"canonicalText":"當怒火欲水正騰沸時，明明知得，又明明犯著。知得是誰，犯著又是誰。此處能猛然轉念，邪魔便為知真君子矣。","sentenceIds":["cai-gen-tan_ch-4_p-46_s-1","cai-gen-tan_ch-4_p-46_s-2","cai-gen-tan_ch-4_p-46_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當憤怒的火焰或情慾的潮水正在心中翻騰沸騰時，明明自己心裡清楚這樣不對，卻又明明去違背理智而犯錯。那麼此時，那個能覺察清醒的人是誰？那個衝動犯錯的人又是誰？如果在此關鍵時刻能夠猛然轉變念頭，那麼心中的邪魔也會立刻轉化為真正的君子。","analysis":"【主題與背景】本段是極具禪宗與心學意味的自我覺察（觀心）法門。作者指出，人在被怒火與欲望支配時，內心其實存在著兩個自我：一個是清醒的覺知（知得），另一個是失控的肉體與情緒（犯著）。\\\\n【詞義與名物】「猛然轉念」就是將注意力從執著的欲望拉回到當下的覺知上，一旦覺知做主，私欲的邪魔自然消退，自性真君子便得以彰顯。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-47","chapterId":"cai-gen-tan_ch-4","order":47,"canonicalText":"毋偏信而為奸所欺，毋自任而為氣所使，毋以己之長而形人之短，毋因己之拙而忌人之能。","sentenceIds":["cai-gen-tan_ch-4_p-47_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不要偏聽偏信而被奸詐之人所欺騙，不要自以為是而被意氣所驅使，不要用自己的長處去比量別人的短處，不要因為自己的笨拙去嫉妒別人的才能。","analysis":"【訓詁與名物】「毋」指不要。「偏信」指只聽信一面之詞。「自任」指自以為是、固執己見。「為氣所使」指被意氣、情緒所控制。「形人之短」指彰顯、對比出別人的缺點。「拙」指愚笨、能力不足。【章法與結構】本段連用四個「毋」字，構成兩組整齊的排比對偶句。前兩句「毋偏信...毋自任...」是從自身心態的內在修養說起，告誡人們要保持理智；後兩句「毋以己之長...毋因己之拙...」則是從人際交往的外在表現著眼，勸誡人們要平等包容。層次分明，語氣懇切。【思想與義理】這段話指出了為人處世最容易犯的四種過失：盲從、任性、驕傲、嫉妒。作者教導我們要兼聽則明，剋制情緒，同時要具備寬廣的胸懷，不恃才傲物，也不因自身不足而生嫉妒之心。這體現了儒家「克己復禮」與「推己及人」的道德修養標準，有助於建立圓融和諧的人際關係。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-48","chapterId":"cai-gen-tan_ch-4","order":48,"canonicalText":"人之短處，要曲為彌縫，如暴而揚之，是以短攻短；人有頑的，要善為化誨，如忿而嫉之，是以頑濟頑。","sentenceIds":["cai-gen-tan_ch-4_p-48_s-1","cai-gen-tan_ch-4_p-48_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"對於別人的缺點，要委婉地替他掩飾彌補，如果將其暴露並宣揚出去，這就是用自己的缺點去攻擊別人的缺點；對於性格固執愚昧的人，要善意地去感化教導他，如果因此對他感到憤怒並憎恨他，這就是用自己的愚昧去助長別人的愚昧。","analysis":"【訓詁與名物】「短處」指缺點或過失。「曲為彌縫」指委婉地替別人掩蓋、彌補過失。「暴」同「曝」，指暴露。「頑的」指冥頑不靈、固執愚蠢的人。「化誨」指感化教誨。「忿」指憤怒。「濟」指助長、增加。【章法與結構】本段以工整的對仗形式呈現，分別針對「人之短處」與「人有頑的」提出應對之道。句式皆採用先提出正確做法（「要曲為彌縫」、「要善為化誨」），再假設錯誤做法（「如暴而揚之」、「如忿而嫉之」），最後點出錯誤做法的荒謬本質（「是以短攻短」、「是以頑濟頑」），正反對比，邏輯極為嚴密。【思想與義理】此句體現了深厚的寬容精神與教育智慧。作者認為，揭發別人的短處，本身就是一種刻薄無情的「短處」；憎惡別人的愚頑，本身也是一種缺乏修養的「愚頑」。真正的君子應該以寬厚的胸襟去包容他人的過失，用善意去感化愚昧，這才是提升自我境界、化解人際矛盾的根本之道。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-49","chapterId":"cai-gen-tan_ch-4","order":49,"canonicalText":"遇沉沉不語之士，且莫輸心；見悻悻自好之人，應須防口。","sentenceIds":["cai-gen-tan_ch-4_p-49_s-1","cai-gen-tan_ch-4_p-49_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遇到那種城府極深、沉默寡言的人，暫時不要輕易向他傾吐真心；見到那種滿懷怨恨、自以為是的人，必須要注意管好自己的嘴巴，防止說錯話惹禍。","analysis":"【訓詁與名物】「沉沉不語」形容人心思深沉、不愛說話，常指城府很深的人。「輸心」指推心置腹，毫無保留地傾吐內心想法。「悻悻自好」形容人脾氣暴躁、怨恨不平且自以為是，聽不進別人的意見。「防口」指謹言慎行，防止言多必失。【章法與結構】本段是標準的兩句對仗，對仗極為工整。「沉沉不語之士」對應「悻悻自好之人」，「且莫輸心」對應「應須防口」。前一句著眼於防備他人的暗算，後一句著眼於避免觸怒他人，兩句相輔相成，簡潔明快地勾勒出兩種典型的人物性格與應對策略。【思想與義理】這段話充滿了中國傳統社會的處世智慧與明哲保身的防禦哲學。人心隔肚皮，對於城府深沉者，若輕易交心，容易遭到背叛與利用；而對於暴躁自負者，若口不擇言，極易引火燒身。作者提醒我們在複雜的人際交往中，必須具備識人的眼光與謹言慎行的自制力，這是在紛擾世間保全自我的重要法則。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-50","chapterId":"cai-gen-tan_ch-4","order":50,"canonicalText":"念頭昏散處，要知提醒；念頭喫緊時，要知放下。不然恐去昏昏之病，又來憧憧之擾矣。","sentenceIds":["cai-gen-tan_ch-4_p-50_s-1","cai-gen-tan_ch-4_p-50_s-2","cai-gen-tan_ch-4_p-50_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當心念昏沉渙散的時候，要知道自我提醒，保持清醒；當心念過於緊張執著的時候，要知道學會放下，放鬆心情。否則，恐怕剛剛去除了昏沉散漫的毛病，又招來了思緒紛亂不寧的煩擾。","analysis":"【訓詁與名物】「昏散」指精神昏沉、注意力渙散。「喫緊」指緊張、執著、糾結於某事。「放下」是佛教用語，指解除心中的執念與執著。「昏昏」指神志不清、迷糊的狀態。「憧憧」指心神不定、思緒紛亂的樣子，語出《易經》「憧憧往來，朋從爾思」。【章法與結構】本段先以對仗句式指出修心過程中兩種極端的心理狀態及其對治方法：「昏散」需「提醒」，「喫緊」需「放下」。接著以「不然」為轉折，點出如果不掌握這兩種調節方法，就會陷入「去昏昏...來憧憧」的惡性循環，首尾呼應，說理透徹。【思想與義理】這段話蘊含了豐富的心理調節與禪宗修行的智慧。人的心理狀態常在兩個極端之間擺盪：要麼過於鬆懈（昏散），要麼過於緊繃（喫緊）。作者強調修心必須掌握「中道」，既不能放縱思緒，也不能過度執著。只有懂得適時提醒與及時放下，才能讓心靈保持在一種清明、安寧且自在的狀態。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-51","chapterId":"cai-gen-tan_ch-4","order":51,"canonicalText":"霽日青天，倏變為迅雷震電；疾風怒雨，倏轉為朗月晴空。氣機何嘗一毫凝滯，太虛何嘗一毫障蔽，人之心體亦當如是。","sentenceIds":["cai-gen-tan_ch-4_p-51_s-1","cai-gen-tan_ch-4_p-51_s-2","cai-gen-tan_ch-4_p-51_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"晴朗的天空，可能會突然變成雷電交加的壞天氣；而狂風暴雨，也可能會突然轉變為明月當空的晴朗夜空。大自然的氣機運轉何嘗有過一絲一毫的停滯？廣闊的太虛天空何嘗有過一絲一毫的遮蔽？人的本心也應當像這樣，不被任何事物所凝滯或蒙蔽。","analysis":"【訓詁與名物】「霽日」指雨後放晴的太陽。「倏」音ㄕㄨˋ，突然。「氣機」指大自然陰陽之氣的運轉機制。「太虛」指廣大無垠的天空，也指宇宙的本體。「心體」指人心的本體、本性。「凝滯」指停滯不前。「障蔽」指遮擋、蒙蔽。【章法與結構】本段先描繪大自然兩種極端的氣候變化（晴轉雷，雨轉晴），營造出瞬息萬變的動態感。接著用兩個反問句（「氣機何嘗...」、「太虛何嘗...」）強調自然本體的暢達無礙。最後筆鋒一轉，將自然現象昇華至人生哲學，以「人之心體亦當如是」作結，由景入理，渾然天成。【思想與義理】此段文字深受宋明理學與禪宗思想的影響。大自然的風雨雷電雖然變幻莫測，但宇宙的本體（太虛）卻始終清明空靈，不曾受損。作者以此為喻，說明人的一生也會經歷順境與逆境的無常變化，但我們的心靈本體應當如同太虛一般，保持空靈明覺，不被外在的悲歡得失所凝滯或蒙蔽，隨遇而安，展現出超然物外的人生境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-52","chapterId":"cai-gen-tan_ch-4","order":52,"canonicalText":"勝私制欲之功，有曰識不早、力不易者，有曰識得破、忍不過者。蓋識是一顆照魔的明珠，力是一把斬魔的慧劍，兩不可少也。","sentenceIds":["cai-gen-tan_ch-4_p-52_s-1","cai-gen-tan_ch-4_p-52_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"關於戰勝私心、剋制慾望的修養功夫，有的人失敗是因為「察覺不夠早、決心不夠堅定」，有的人失敗則是因為雖然「能看破慾望的虛妄、卻無法忍受誘惑」。因為察覺的智慧就像是一顆能照妖除魔的明珠，而剋制的毅力就像是一把能斬妖除魔的慧劍，這兩者在修身過程中是缺一不可的。","analysis":"【訓詁與名物】「勝私制欲」指戰勝私心、剋制物慾。「識」指察覺、認識，即智慧與洞察力。「力」指決心、毅力。「識得破」指能看穿事物的虛幻本質。「照魔的明珠」比喻能照破無明煩惱的智慧之光。「斬魔的慧劍」比喻能斬斷煩惱牽絆的堅定意志。\\\\n【章法與結構】此段先提出「勝私制欲」的兩種失敗情況：「識不早、力不易」與「識得破、忍不過」。接著以「蓋」字承接，對「識」與「力」進行形象化的比喻，將其分別比作「明珠」與「慧劍」，最後以「兩不可少也」作結，邏輯嚴密，說理生動。\\\\n【思想與義理】這段話探討了儒佛兩家在心性修養上的方法論。作者認為，要克服內心的私慾，必須具備「知」與「行」兩個條件：「識」代表著認知上的覺醒，能看清慾望的危害；「力」代表著實踐上的剋制，能抵禦慾望的誘惑。這與王陽明「知行合一」的理念相契合，強調了修身不僅需要高超的見解，更需要堅韌的意志。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-53","chapterId":"cai-gen-tan_ch-4","order":53,"canonicalText":"橫逆困窮，是煆煉豪傑的一副爐錘。能受其煆煉者，則身心交益；不受其煆煉者，則身心交損。","sentenceIds":["cai-gen-tan_ch-4_p-53_s-1","cai-gen-tan_ch-4_p-53_s-2","cai-gen-tan_ch-4_p-53_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遭遇突如其來的災禍以及陷入困苦窮困的境地，這些都是用來鍛鍊英雄豪傑的火爐與鐵鎚。能夠承受得住這種艱苦鍛鍊的人，他的身體與心靈都會獲得極大的益處；如果無法承受這種鍛鍊的人，他的身體與心靈就會同時受到嚴重的損害。","analysis":"【訓詁與名物】「橫逆」指突如其來、不合情理的災禍與挫折。「困窮」指生活困苦、走投無路。「煆煉」同「鍛鍊」，指將金屬加熱捶打使其精純，此比喻經歷磨難以堅強意志。「爐錘」指打鐵用的火爐與鐵鎚，比喻嚴酷的考驗。「交益」指身心雙方面都受益。「交損」指身心雙方面都受損。\\\\n【章法與結構】此段首句運用暗喻，將「橫逆困窮」比作「爐錘」，極具震撼力。其後兩句則採用正反對比的手法，分別論述「能受其煆煉」與「不受其煆煉」的兩種截然不同的結果（身心交益 vs. 身心交損），對仗工整，語氣堅定。\\\\n【思想與義理】這段話呼應了孟子「生於憂患，死於安樂」以及「天將降大任於是人也」的思想。作者認為，逆境與挫折並非絕對的壞事，它們是檢驗與成就偉大人物的試金石。面對困境，唯有勇敢迎接挑戰，將其視為磨練心志的機會，才能轉危為安、破繭而出；反之，若被困境擊倒，便會徹底沉淪。這展現了積極向上、不畏艱難的人生觀。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-54","chapterId":"cai-gen-tan_ch-4","order":54,"canonicalText":"害人之心不可有，防人之心不可無，此戒疎於慮者。寧受人之欺，毋逆人之詐，此警傷於察者。二語並存，精明渾厚矣。","sentenceIds":["cai-gen-tan_ch-4_p-54_s-1","cai-gen-tan_ch-4_p-54_s-2","cai-gen-tan_ch-4_p-54_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"「害人的心思不可以有，防範別人的心思不可以無」，這是用來戒備那些考慮事情過於疏忽大意的人；「寧可承受別人的欺騙，也不要預先去無端猜測別人的奸詐」，這是用來警告那些觀察過於苛刻偏激的人。將這兩句話結合起來並存於心，就能同時做到做人精明且待人渾厚了。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈閒適〉第 273 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「害人之心不可有防人之心不可無此戒疎於慮者……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「害」、「人」、「之」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-4_p-54）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-55","chapterId":"cai-gen-tan_ch-4","order":55,"canonicalText":"毋因羣疑而阻獨見，毋任己意而廢人言，毋私小惠而傷大體，毋借公論以快私情。","sentenceIds":["cai-gen-tan_ch-4_p-55_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不要因為眾人的懷疑而阻礙了自己獨到的見解，不要放任自己的主觀意願而廢棄了別人的合理規勸；不要因為私下施予小恩小惠而損害了整體的利益與大局，不要假借社會公眾的輿論來發洩私人的恩怨情仇。","analysis":"【主題與背景】本段提出了做人做事的四個「毋」字準則，涵蓋了認知、態度、格局與動機。在思維上，既要有堅持真理的獨立思考（不因羣疑阻獨見），又要有虛懷若谷的包容度（不任己意廢人言）；在行事上，要分清輕重緩急（不私小惠傷大體），並保持動機的純潔，不搞公器私用（不借公論快私情）。\\\\n【詞義與名物】這是一套非常實用的中庸管理與修身智慧。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-56","chapterId":"cai-gen-tan_ch-4","order":56,"canonicalText":"善人未能急親，不宜預揚，恐來讒譖之奸；惡人未能輕去，不宜先發，恐招媒孽之禍。","sentenceIds":["cai-gen-tan_ch-4_p-56_s-1","cai-gen-tan_ch-4_p-56_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遇到善良正直的人，如果還無法立刻親近結交，就不應該過早地四處讚揚他，以免引來小人的嫉妒與毀謗；遇到邪惡險詐的人，如果還無法輕易地將其除掉，就不應該先發制人地暴露自己的意圖，以免招致小人羅織罪名、暗中陷害的災禍。","analysis":"【訓詁與名物】「急親」指立刻親近。「預揚」指過早地讚揚。「讒譖之奸」指小人造謠毀謗、挑撥離間的奸惡行為。「輕去」指輕易地除掉、擺脫。「先發」指先採取行動或暴露意圖。「媒孽」比喻羅織罪名、構陷他人。「媒孽之禍」指被陷害的災禍。\\\\n【章法與結構】這是一組對偶極其工整的駢句。「善人」對「惡人」，「未能急親」對「未能輕去」，「不宜預揚」對「不宜先發」，「恐來讒譖之奸」對「恐招媒孽之禍」。兩句皆採用假設條件句式，提出在特定情境下應有的謹慎態度。\\\\n【思想與義理】此段反映了作者深諳世故與險惡官場的生存哲學。在複雜的人際網絡中，無論是褒揚善人還是懲治惡人，都需要講究時機與策略。過早暴露自己的好惡，不僅無法達到預期目的，反而容易成為小人攻擊的把柄。這提醒人們在處世時必須謹言慎行、韜光養晦，體現了老道圓熟的處世智慧與自我保護意識。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-57","chapterId":"cai-gen-tan_ch-4","order":57,"canonicalText":"青天白日的節義，自暗室屋漏中培來；旋乾轉坤的經綸，從臨深履薄中操出。","sentenceIds":["cai-gen-tan_ch-4_p-57_s-1","cai-gen-tan_ch-4_p-57_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如同青天白日般光明磊落的節操與道義，是從無人看見的暗室與屋漏等隱微之處默默培養出來的；具有扭轉乾坤之能的雄才大略與治國方策，是從如臨深淵、如履薄冰的謹慎實踐中磨練出來的。","analysis":"【主題與背景】本段揭示了偉大的人格與非凡的才幹背後的修行過程。光明磊落的「節義」並非作秀，而是源於在無人監督的私密空間（暗室屋漏）中日復一日的自律與慎獨；而驚天動地的「經綸」才幹，也不是憑空產生的，而是在如履薄冰的細緻工作中，通過無數次謹慎的實踐逐漸累積而成。\\\\n【詞義與名物】這體現了「積土成山，風雨興焉」的道理。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-58","chapterId":"cai-gen-tan_ch-4","order":58,"canonicalText":"父慈子孝、兄友弟恭，縱做到極處，俱是合當如是，著不得一毫感激的念頭。如施者任德，受者懷恩，便是路人，便成市道矣。","sentenceIds":["cai-gen-tan_ch-4_p-58_s-1","cai-gen-tan_ch-4_p-58_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"父親慈愛、兒子孝順，兄長友善、弟弟恭敬，這些家庭倫理即使做到了最完美的境界，也全都是理所當然、本該如此的本分，心中容不得有絲毫要求對方感激的念頭。如果付出愛的人自以為有恩德，接受愛的人則心懷感恩想要回報，那麼親人之間就變得像陌生人一樣，這種關係也就變成建立在利益交換上的市儈行為了。","analysis":"【訓詁與名物】「父慈子孝、兄友弟恭」儒家提倡的家庭基本倫理規範。「合當如是」指理所當然，本來就應該這樣。「著不得」指容不下、不能有。「任德」指自以爲有恩德。「懷恩」指心懷感恩。「路人」指沒有血緣關係的陌生人。「市道」指市場上買賣交易的法則，引申為利益交換的功利關係。\\\\n【章法與結構】此段先樹立一個絕對的道德標準：家庭倫理的實踐是「合當如是」，不容許有任何功利色彩。接著以「如」字作反面假設，指出如果將親情視為施恩與圖報，就會淪為「路人」與「市道」。正反論證，將親情的純粹性推向了極致。\\\\n【思想與義理】這段話是對儒家傳統倫理的一種極致昇華。作者認為，真正的親情應該是發自天然本性的無條件付出，而不應該摻雜任何功利與交換的算計。如果將社會上的人情世故（施恩圖報）套用於家庭之中，不僅是對親情的褻瀆，更會破壞家庭的凝聚力。這呼籲人們回歸純真無私的至性至情，批判了世俗化、功利化的人際交往模式。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-59","chapterId":"cai-gen-tan_ch-4","order":59,"canonicalText":"炎涼之態，富貴更甚於貧賤；妒忌之心，骨肉尤狠於外人。此處若不當以冷腸，御以平氣，鮮不日坐煩惱障中矣。","sentenceIds":["cai-gen-tan_ch-4_p-59_s-1","cai-gen-tan_ch-4_p-59_s-2","cai-gen-tan_ch-4_p-59_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"世態炎涼的趨炎附勢與冷酷無情，在富貴人家比在貧賤之家中表現得更為嚴重；嫉妒的心態，在骨肉至親之間有時候比在毫無關係的外人之間還要狠毒。在面對這些情況時，如果不以冷靜冷淡的心腸去對待，不用平和沉著的脾氣去抵禦，很少有人能不天天陷入煩惱與痛苦的魔障之中。","analysis":"【主題與背景】此段揭示了人性的陰暗面與處之之道。在物質利益集中的富貴環境中，人情的冷暖更顯赤裸；在關係最緊密的家族內部，攀比引發的嫉妒往往比外人更為激烈。\\\\n【詞義與名物】作者警示世人要對此有清醒的認識，並開出「冷腸」與「平氣」的處方——以冷淡的超然態度與平和的心態來面對這些家庭與世俗的醜陋，避免讓自己陷入無盡的痛苦與怨恨。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-60","chapterId":"cai-gen-tan_ch-4","order":60,"canonicalText":"功過不宜少混，混則人懷惰隳之心；恩仇不可太明，明則人起攜貳之志。","sentenceIds":["cai-gen-tan_ch-4_p-60_s-1","cai-gen-tan_ch-4_p-60_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"對他人的功勞與過錯不應當有絲毫的混淆，一旦混淆了賞罰，人們就會產生懈怠與荒廢的心思；對於私人恩怨與仇恨不可分得太清、算得太明，一旦表現得過於壁壘分明，人們就會產生離心離德、背叛反叛的念頭。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈閒適〉第 279 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「功過不宜少混混則人懷惰隳之心恩仇不可太明……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「功」、「過」、「不」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-4_p-60）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-61","chapterId":"cai-gen-tan_ch-4","order":61,"canonicalText":"惡忌陰，善忌陽，故惡之顯者禍淺，而隱者禍深。善之顯者功小，而隱者功大。","sentenceIds":["cai-gen-tan_ch-4_p-61_s-1","cai-gen-tan_ch-4_p-61_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"做惡事最忌諱的是隱瞞不露，做善事最忌諱的是四處張揚。因此，那些明顯暴露出來的惡行，其造成的災禍往往比較淺；而那些隱藏在暗處的惡行，其造成的災禍卻十分深重。那些公然顯露、為人所知的善行，其功德往往比較小；而那些默默無聞、不為人知的善行，其功德卻是巨大的。","analysis":"【訓詁與名物】「惡忌陰」指做惡事忌諱隱藏暗處。「善忌陽」指做善事忌諱張揚顯露。「陰」指隱密、不為人知。「陽」指公開、顯露。「顯者」指表現出來的。「隱者」指隱藏起來的。「功」指功德、福報。\\\\n【章法與結構】此段以極其簡練的「惡忌陰，善忌陽」作為全篇綱領。隨後以「故」字引出兩組對比：「惡之顯者」對「隱者」，「善之顯者」對「隱者」。透過顯隱、深淺、大小的對比，將善惡的表現形式與其產生的後果進行了辯證的分析。\\\\n【思想與義理】這段話蘊含了深厚的道家與佛家思想。在道家看來，「大音希聲，大象無形」，真正的善行應該是自然而然、不求名聲的「陰德」；如果刻意張揚以求回報（陽善），其道德價值便大打折扣。反之，惡行若能坦然承認（顯惡），尚有悔改的可能；若刻意掩蓋（陰惡），則會逐漸腐蝕人心，帶來更可怕的後果。這教導人們要修積陰德，並勇於面對自己的過失。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-62","chapterId":"cai-gen-tan_ch-4","order":62,"canonicalText":"德者才之主，才者德之奴；有才無德如家無主，而奴用事矣，幾何不魍魎猖狂。","sentenceIds":["cai-gen-tan_ch-4_p-62_s-1","cai-gen-tan_ch-4_p-62_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"品德是才華的主人，才華是品德的奴僕；如果一個人只有才華而沒有品德，就如同一個家庭沒有了主人，卻讓奴僕來當家做主，這樣一來，怎麼可能不落得妖魔鬼怪猖狂作亂的下場呢？","analysis":"【訓詁與名物】\\\\n德：品德，道德修養。才：才能，才華。主：主人，主導者。奴：奴僕，受支配者。用事：當權，掌管事務。幾何：多少，此處引申為「怎麼會」、「哪能」。魍魎：傳說中的山川精怪，此處比喻邪惡的念頭或小人。猖狂：狂妄放肆，為所欲為。\\\\n【章法與結構】\\\\n本段運用了生動的比喻與嚴整的對比。「德」與「才」被擬人化為「主」與「奴」，將抽象的道德與才華具象化。前兩句直接點明德才的主從關係，後三句則透過「家無主而奴用事」的譬喻，推導出「魍魎猖狂」的災難性後果。邏輯層層遞進，說理透徹有力。\\\\n【思想與義理】\\\\n本段深刻闡述了儒家「尊德性」而「道問學」的核心觀念，強調了品德在個人修養中的統帥地位。才華只是工具與手段，必須由善良的品德來駕馭，才能造福社會。如果才華脫離了道德的約束，就如同失去了主人的奴僕竊取了權力，不但不能成事，反而會因為才華出眾而造成更大的破壞與禍患。這警示人們在追求能力提升的同時，絕不可忽視品格的涵養。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-63","chapterId":"cai-gen-tan_ch-4","order":63,"canonicalText":"鋤奸杜倖，要放他一條去路。若使之一無所容，便如塞鼠穴者，一切去路都塞盡，則一切好物都咬破矣。","sentenceIds":["cai-gen-tan_ch-4_p-63_s-1","cai-gen-tan_ch-4_p-63_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"剷除奸臣、杜絕小人投機取巧的時候，要給他們留下一條退路。如果逼得他們無處容身，就像堵塞老鼠洞一樣，把所有的出路都堵死了，老鼠無處可逃，就會把家裡所有珍貴的物品都咬壞。","analysis":"【主題與背景】此段提出了政治鬥爭與人際處理的「留餘地」智慧。作者以「塞鼠穴」為生動比喻，指出在對付小人與奸邪時，如果逼人太甚、不留生路（使之一無所容），往往會激發對方作魚死網破的拼死反撲，給自身或社會帶來更大的破壞。\\\\n【詞義與名物】因此，適當給予一條退路，可以分散其反抗力量，以較小代價達成治理目的。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-64","chapterId":"cai-gen-tan_ch-4","order":64,"canonicalText":"士君子貧不能濟物者，遇人癡迷處，出一言提醒之，遇人急難處，出一言解救之，亦是無量功德矣。","sentenceIds":["cai-gen-tan_ch-4_p-64_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"讀書人與君子如果因為貧窮而無法在物質上接濟別人，那麼在遇到別人執迷不悟的時候，說一句話來提醒他們；在遇到別人遭遇緊急危難的時候，說一句話來解救他們，這也是無法估量的巨大功德。","analysis":"【訓詁與名物】\\\\n士君子：泛指有道德、有學問的知識份子。濟物：救濟他人或事物。癡迷：沉迷不悟，失去理智判斷。急難：緊急危難的情況。無量：沒有限量，不可估量。功德：佛教用語，指善行所帶來的福報，此泛指善行的價值。\\\\n【章法與結構】\\\\n本段採用假設與排比的句式。首先設定了一個「貧不能濟物」的前提，接著以「遇人癡迷處」與「遇人急難處」作為兩個並列的情境，分別給出「出一言提醒之」與「出一言解救之」的行動方案，最後以「無量功德」作為總結。語言平實質樸，結構清晰對稱。\\\\n【思想與義理】\\\\n這段話打破了世俗對於「行善」的狹隘定義，強調善行不僅限於物質上的金錢施捨，更包含精神上與智慧上的幫助。言語的力量有時勝過真金白銀，一句適時的提醒或解圍，足以改變他人的命運或挽救一場危機。這體現了儒家「仁者愛人」的精神與佛教的「法施」觀念，鼓勵人們無論貧富，都能在日常生活中隨分隨力地行善積德，彰顯人性的光輝。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-65","chapterId":"cai-gen-tan_ch-4","order":65,"canonicalText":"處己者觸事皆成藥石，尤人者動念即是戈矛，一以闢眾善之路，一以濬諸惡之源，相去霄壤矣。","sentenceIds":["cai-gen-tan_ch-4_p-65_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"嚴於律己、時常反省自己的人，遇到任何事情都能成為治病的良藥；總是怨天尤人、怪罪別人的人，只要心念一動就如同動用了刀槍武器。前者以此開闢了通往各種善行的大道，後者卻以此挖深了各種罪惡的泉源，兩者之間的差距就像天與地一樣遙遠。","analysis":"【訓詁與名物】\\\\n處己：對待自己，此處引申為要求自己、反求諸己。藥石：治病的藥物與砭石，比喻能治病救人、改過自新的良規與教誨。尤人：怨恨、責怪別人（典出《論語》「不怨天，不尤人」）。戈矛：古代的兵器，比喻傷害他人的言行或敵意。闢：開闢，打開。濬：疏通，挖深。霄壤：天與地，比喻相差極大。\\\\n【章法與結構】\\\\n全段以極其工整的駢偶句式寫成。「處己」與「尤人」相對，「藥石」與「戈矛」相對；「闢眾善之路」與「濬諸惡之源」相對。透過正反兩面的強烈對比，清楚揭示了兩種截然不同的人生態度及其後果，最後以「相去霄壤」作結，發人深省。\\\\n【思想與義理】\\\\n本段闡發了儒家「反求諸己」與「克己復禮」的修養功夫。面對逆境或衝突，如果能自我反省，那麼一切挫折都會成為提升自我境界的逆增上緣；反之，如果一味推諉卸責、指責他人，內心就會充滿怨恨與敵意，進而引發無休止的紛爭與罪惡。心唸的一轉，決定了人生的方向是走向光明至善，還是墮入黑暗深淵，這提醒我們必須時刻觀照自己的起心動念。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-66","chapterId":"cai-gen-tan_ch-4","order":66,"canonicalText":"事業文章隨身銷毀，而精神萬古如新；功名富貴逐世轉移，而氣節千載一時。羣信不以彼易此也。","sentenceIds":["cai-gen-tan_ch-4_p-66_s-1","cai-gen-tan_ch-4_p-66_s-2","cai-gen-tan_ch-4_p-66_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"世俗的事業與文章會隨著肉身的消亡而毀壞，但崇高的精神卻能萬古長存、歷久彌新；功名與富貴會隨著世代的變遷而轉移，但高尚的氣節卻能千載如一日。大家應該相信，絕不可用那不朽的精神與氣節，去換取那短暫的事業與富貴。","analysis":"【訓詁與名物】\\\\n隨身銷毀：隨著身體的死亡而消散毀滅。萬古如新：經歷萬代依然像新的一樣，指精神永不磨滅。逐世轉移：隨著時代或世事的變遷而改變擁有者。千載一時：千年如同一時，指氣節始終如一，永恆不變。羣信：疑為「君信」之誤，或解作「眾人應當相信」。易：交換，替代。\\\\n【章法與結構】\\\\n本段採用了兩組駢偶句來進行對比：「事業文章」對「功名富貴」，「隨身銷毀」對「逐世轉移」，「精神萬古如新」對「氣節千載一時」。前兩句對舉，將短暫的世俗成就與永恆的精神價值並列，最後一句「羣信不以彼易此也」畫龍點睛，作為全段的結論與勸勉，語氣堅定。\\\\n【思想與義理】\\\\n這段話探討了生命中「變」與「不變」、「短暫」與「永恆」的哲學命題。外在的功利成就、財富地位，甚至文學才華，都會受到時間與無常的洗刷而灰飛煙滅；然而，內在的高尚品格與凜然氣節，卻能超越時空的限制，成為人類共同的精神財富。作者以此勉勵世人，不要為了追求眼前轉瞬即逝的虛榮，而喪失了最寶貴且能萬古流芳的道德操守。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-67","chapterId":"cai-gen-tan_ch-4","order":67,"canonicalText":"魚網之設，鴻則罹其中；螳螂之貪，雀又乘其後。機裏藏機變外生變，智巧何足恃哉。","sentenceIds":["cai-gen-tan_ch-4_p-67_s-1","cai-gen-tan_ch-4_p-67_s-2","cai-gen-tan_ch-4_p-67_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"設置捕魚的網，原本是用來抓魚的，有時卻是鴻雁誤觸羅網被困在其中；螳螂貪圖眼前的蟬，卻不知道黃雀正趁機潛伏在牠的身後。這世間的機關之中還隱藏著機關，變故之外又會生出變故，個人的機智與巧算又哪裡值得依靠呢？","analysis":"【訓詁與名物】\\\\n魚網之設，鴻則罹其中：典出《詩經·邶風·新臺》「魚網之設，鴻則離之」，原意是設網捕魚，卻捕到了鴻雁；比喻事情的發展出乎意料，或無辜者受害。罹：遭受，困於。螳螂之貪，雀又乘其後：典出《莊子·山木》與《說苑·正諫》的「螳螂捕蟬，黃雀在後」，比喻只顧眼前的利益，卻沒發覺身後隱藏的危機。機：機關，計謀。恃：依賴，仗恃。\\\\n【章法與結構】\\\\n本段前半部引用了《詩經》與《莊子》中的兩個著名典故，形成工整的對偶，生動形象地展示了世事的不可預測性。後半部則以「機裏藏機變外生變」進行理論上的概括，最後以「智巧何足恃哉」的反問句作結，將整段的哲理推向高潮，具有強烈的警世意味。\\\\n【思想與義理】\\\\n這段文字傳達了道家「大智若愚」與反對過度用心機的哲學思想。宇宙萬物之間的關聯錯綜複雜，因果網絡牽一髮而動全身，絕非個人的小聰明所能完全掌控。如果一味依恃智巧去算計別人或謀取利益，往往會落入別人設下的另一個圈套，或是遭遇不可預知的變故。因此，為人處世應當放下機心，返璞歸真，順應自然法則，方能免於災禍。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-68","chapterId":"cai-gen-tan_ch-4","order":68,"canonicalText":"作人無一點真懇的念頭，便成個花子，事事皆虛；涉世無一段圓活的機趣，便是個木人，處處有礙。","sentenceIds":["cai-gen-tan_ch-4_p-68_s-1","cai-gen-tan_ch-4_p-68_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"做人如果沒有一點真誠懇切的心意，就會變成一個虛有其表的乞丐（或騙子），做任何事情都是虛假不實的；在社會上為人處世，如果沒有一點圓融靈活的機智與情趣，就會變成一個僵硬呆板的木頭人，無論走到哪裡都會遇到障礙與阻力。","analysis":"【訓詁與名物】：「真懇」指真誠、懇切。「花子」在古代多指乞丐或虛浮不實、招搖撞騙之人，此處取其虛浮不實之意。「虛」指虛假、落空。「涉世」指經歷世事、與社會打交道。「圓活」指圓融、靈活、變通。「機趣」指機智與情趣。「木人」比喻呆板、僵化、不知變通的人。「有礙」指遇到阻礙、行不通。\\\\n\\\\n【章法與結構】：本段以兩組工整的對偶句構成。「作人」對「涉世」，「無一點真懇的念頭」對「無一段圓活的機趣」，「便成個花子」對「便是個木人」，「事事皆虛」對「處處有礙」。前句講內在的誠意，後句講外在的變通；前句用「花子」作喻，後句用「木人」作比，形式對稱，寓意深刻。\\\\n\\\\n【思想與義理】：此段論述了「誠」與「通」的人生哲學。「真懇」是儒家強調的立身之本，《中庸》雲：「誠者，天之道也；誠之者，人之道也。」沒有真誠，人生便如無根之木，一切成就皆是虛幻。而「圓活」則是道家與兵法所推崇的處世智慧，在複雜的社會環境中，如果過於僵化刻板，不知變通，必然會處處碰壁。內具真誠之體，外具圓融之用，方能立於不敗之地。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-69","chapterId":"cai-gen-tan_ch-4","order":69,"canonicalText":"有一念而犯鬼神之忌，一言而傷天地之和，一事而釀子孫之禍者，最宜切戒。","sentenceIds":["cai-gen-tan_ch-4_p-69_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果有一種念頭會觸犯鬼神的禁忌，有一句話會破壞天地間的和諧之氣，有一件事會為後代子孫釀成災禍，這些都是最應該堅決戒除的。","analysis":"【訓詁與名物】：「一念」指一個微小的念頭。「鬼神之忌」指冥冥之中違背天理、招致神明懲罰的禁忌。「一言」指一句隨口說出的話。「天地之和」指宇宙間陰陽調和、萬物共生的和諧狀態，也可指人際關係的和睦。「釀」指孕育、造成。「子孫之禍」指延續給後代的災禍。「切戒」指務必堅決地戒除、防範。\\\\n\\\\n【章法與結構】：這句話採用了排比的修辭手法，由三個並列的條件句「有一念而……，一言而……，一事而……」構成，從「念」（思想）、「言」（語言）、「事」（行為）三個層次層層遞進，涵蓋了人生的各個方面。最後以「最宜切戒」總結全句，語氣莊重，具有強烈的警告意味。\\\\n\\\\n【思想與義理】：這段話反映了中國傳統文化中的因果報應觀與深沉的敬畏之心。「一念」、「一言」、「一事」看似微不足道，但若違背了道德倫理與自然規律（鬼神之忌、天地之和），不僅會給自己帶來禍患，甚至會禍及子孫。這要求人們在日常生活中必須做到「慎獨」，在起心動念、言談舉止間都要嚴格要求自己，保持對天理良知的敬畏，積善成德，以造福後代。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-70","chapterId":"cai-gen-tan_ch-4","order":70,"canonicalText":"事有急之不白者，寬之或自明，毋躁急以速其忿；人有切之不從者，縱之或自化，毋操切以益其頑。","sentenceIds":["cai-gen-tan_ch-4_p-70_s-1","cai-gen-tan_ch-4_p-70_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"有些事情，你越是急於去辯白澄清，反而越說不清楚；如果放寬心態、暫緩處理，有時候它自己就會真相大白，所以千萬不要因為急躁而加速激化雙方的憤怒。有些人，你越是嚴厲地去逼迫他順從，他反而越不聽話；如果適當地放任、給予空間，有時候他自己就會幡然醒悟而改變，所以千萬不要因為操之過急而助長了他的頑固不化。","analysis":"【訓詁與名物】：「急之不白」指越著急越無法澄清事實。「寬之」指放寬期限、暫緩處理。「自明」指自然而然地水落石出。「毋」意為不要。「躁急」指急躁。「速其忿」指加速或招致憤怒，速有招致之意。「切之不從」指嚴厲逼迫對方卻不被順從。「縱之」指放任、放鬆。「自化」指自我感化、自然轉變。「操切」指做事過於急切、手段激烈。「益其頑」指增加、助長其頑固。\\\\n\\\\n【章法與結構】：全段分為兩部分，前半部論「事」，後半部論「人」，句式完全對稱。每部分皆採用了「正反對比」加「總結勸誡」的結構：「急之不白」對「切之不從」，「寬之或自明」對「縱之或自化」，「毋躁急以速其忿」對「毋操切以益其頑」。說理清晰，節奏舒緩而有力。\\\\n\\\\n【思想與義理】：這段話深具道家「無為而治」與「柔弱勝剛強」的智慧。在處理複雜的人際關係與棘手問題時，強攻與急躁往往會適得其反，激化矛盾（速其忿、益其頑）。相反，適當的「留白」與「冷處理」（寬之、縱之），反而能讓時間去平息情緒、揭示真相，讓對方在寬鬆的環境中自我反省與轉變（自明、自化）。這種以退為進、以柔克剛的處世技巧，展現了極高的涵養與人生智慧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-71","chapterId":"cai-gen-tan_ch-4","order":71,"canonicalText":"節義傲青雲，文章高白雪，若不以德性陶鎔之，終為血氣之私、技能之末。","sentenceIds":["cai-gen-tan_ch-4_p-71_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一個人的氣節與道義即便高尚到可以傲視青雲（達官貴人），寫出的文章即便高妙到如同《陽春白雪》般超凡脫俗，但如果不使用淳厚的道德品性來加以陶冶和鎔鑄，那麼這些氣節終究只是出於個人一時衝動的血氣之勇，這些文章終究也只是微不足道的文字雕蟲小技罷了。","analysis":"【訓詁與名物】：「節義」指氣節與道義。「傲青雲」指傲視顯貴，青雲借指高官顯爵或極高的地位。「白雪」指古代高雅的琴曲《陽春白雪》，此處比喻文章格調高雅。「陶鎔」原指燒製陶器與冶煉金屬，此處引申為教育、培養與薰陶。「血氣之私」指憑藉一時的血氣衝動與個人私意所表現出的剛強。「技能之末」指微不足道的技藝與技巧。\\\\n\\\\n【章法與結構】：本段開篇以兩個極具氣勢的誇張比喻「節義傲青雲」與「文章高白雪」起筆，先將人的氣節與才華推向極致；隨後筆鋒一轉，用「若不……終為……」的條件假設句式，給予了當頭棒喝。前高後低，形成了強烈的反差，突出了「德性」在人生修養中的核心地位。\\\\n\\\\n【思想與義理】：此段明確闡述了儒家「德為本，才為末」的核心價值觀。在作者看來，節義與才華雖然可貴，但如果缺乏了內在渾厚、仁愛的「德性」作為支撐與化解，所謂的「節義」就容易淪為偏激、狹隘的血氣之勇（如匹夫之勇）；所謂的「文章」也容易流於華而不實的辭藻堆砌（技能之末）。只有將才華與氣節融入到深厚的道德修養之中，才能達到圓融平和、真正造福世人的君子境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-72","chapterId":"cai-gen-tan_ch-4","order":72,"canonicalText":"謝事當謝於正盛之時，居身宜居於獨後之地，謹德須謹於至微之事，施恩務施於不報之人。","sentenceIds":["cai-gen-tan_ch-4_p-72_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"辭去官職或功成身退，應當選擇在事業最為鼎盛的時候；安身立命，適宜處在不與人爭搶、獨自退居眾人之後的位置；注重道德修養，必須在最微小、最不易察覺的事情上謹慎行事；施予別人恩惠，務必要施予那些無力或無法回報自己的人。","analysis":"【訓詁與名物】：「謝事」指辭去職務、卸下責任或功成身退。「正盛之時」指事業發展到最高峯的時期。「居身」指安身立命、為人處世的位置。「獨後之地」指退讓不爭、甘居人後的地步。「謹德」指謹慎地修養品德。「至微之事」指極其細微、小的事情。「施恩」指給予恩惠。「不報之人」指無法回報或不指望其回報的人。\\\\n\\\\n【章法與結構】：這是一組極為工整的排比句，由四個結構相同的分句組成：「……當……於……」，「……宜……於……」，「……須……於……」，「……務……於……」。四個分句分別從「退隱」、「處世」、「修德」、「行善」四個維度，提出了四種看似悖理實則深奧的行為準則，音韻鏗鏘，說理透徹。\\\\n\\\\n【思想與義理】：這段話將道家、儒家與佛家的智慧熔於一爐。「謝事於正盛」體現了老子「功遂身退，天之道」的明智，避免物極必反；「居身於獨後」展現了「夫唯不爭，故天下莫能與之爭」的謙退之德；「謹德於至微」契合了儒家「慎獨」與「防微杜漸」的修身要求；而「施恩於不報」則體現了佛家「無相佈施」的慈悲境界。這四點共同構成了一個圓滿無漏、超越世俗名利的高尚人格範式。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-4_p-73","chapterId":"cai-gen-tan_ch-4","order":73,"canonicalText":"德者事業之基，未有基不固而棟宇堅久者；心者修裔之根，未有根不植而枝葉榮茂者。","sentenceIds":["cai-gen-tan_ch-4_p-73_s-1","cai-gen-tan_ch-4_p-73_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"高尚的道德是建立一切事業的基礎，從來沒有基礎不穩固而房屋卻能堅固持久的；純正的心地是孕育優秀後代的根本，從來沒有樹根不深植於地下而枝葉卻能繁榮茂盛的。","analysis":"【訓詁與名物】\\\\n「德」指道德品格；「基」指建築物的地基；「固」為穩固；「棟宇」泛指房屋建築；「修裔」意指培育優秀的子孫後代（「裔」即後代，亦可解作自身修養的延伸）；「植」指紮根深種；「榮茂」指繁榮茂盛。\\\\n【章法與結構】\\\\n全段由兩個結構完全對稱的意羣組成，皆採用先立論、後比喻反證的手法。「德者事業之基」對「心者修裔之根」，直指核心命題；隨後以「未有基不固而棟宇堅久者」對「未有根不植而枝葉榮茂者」，用「未有……而……」的反問語氣加強論證力度。房屋與樹木的比喻，生動形象地將抽象的德性與心性具象化。\\\\n【思想與義理】\\\\n此段體現了儒家「本立而道生」的核心思想，強調內在道德修養是一切外在成就的前提。事業的成功如同建屋，若無「德」作為地基，再宏偉的事業也終將倒塌；家族的延續與繁榮如同種樹，若無純正的「心」作為根基，子孫後代也無法繁盛。作者告誡世人，切莫捨本逐末，盲目追求外在的功名利祿與家族榮耀，而應將心力投注於內心的修養與品德的建立，這才是萬世不拔的根本。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"cai-gen-tan_ch-4_p-1_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-1","order":1,"canonicalText":"真廉無廉名，立名者正所以為貪；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-1_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-1","order":2,"canonicalText":"大巧無巧術，用術者乃所以為拙。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-2_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-2","order":1,"canonicalText":"心體光明，暗室中有青天；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-2_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-2","order":2,"canonicalText":"念頭闇昧，白日下有厲鬼。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-3_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-3","order":1,"canonicalText":"人知名位為樂，不知無名無位之樂為最真；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-3_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-3","order":2,"canonicalText":"人知飢寒為憂，不知不飢不寒之憂為更甚。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-4_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-4","order":1,"canonicalText":"為惡而畏人知，惡中猶有善路；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-4_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-4","order":2,"canonicalText":"為善而急人知，善處即是惡根。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-5_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-5","order":1,"canonicalText":"天之機緘不測，抑而伸、伸而抑，皆是播弄英雄、顛倒豪傑處。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-5_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-5","order":2,"canonicalText":"君子只是逆來順受、居安思危，天亦無所用其伎倆矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-6_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-6","order":1,"canonicalText":"福不可徼，養喜神以為招福之本；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-6_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-6","order":2,"canonicalText":"禍不可避，去殺機以為遠禍之方。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-7_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-7","order":1,"canonicalText":"十語九中未必稱奇，一語不中，則愆尤駢集；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-7_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-7","order":2,"canonicalText":"十謀九成未必歸功，一謀不成則訾議叢興。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-7_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-7","order":3,"canonicalText":"君子所以寧默毋躁、寧拙毋巧。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-8_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-8","order":1,"canonicalText":"天地之氣，暖則生，寒則殺。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-8_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-8","order":2,"canonicalText":"故性氣清冷者，受享亦涼薄。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-8_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-8","order":3,"canonicalText":"惟氣和暖心之人，其福亦厚，其澤亦長。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-9_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-9","order":1,"canonicalText":"天理路上甚寬，稍遊心胸中，便覺廣大宏朗；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-9_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-9","order":2,"canonicalText":"人慾路上甚窄，纔寄跡眼前，俱是荊棘泥塗。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-10_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-10","order":1,"canonicalText":"一苦一樂相磨練，練極而成福者，其福始久：一疑一信相參勘，勘極而成知者，其知始真。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-11_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-11","order":1,"canonicalText":"地之穢者多生物，水之清者常無魚，故君子當存含垢納污之量，不可持好潔獨行之操。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-12_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-12","order":1,"canonicalText":"泛駕之馬可就馳驅，躍冶之金終歸型範。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-12_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-12","order":2,"canonicalText":"只一優遊不振，便終身無個進步。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-12_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-12","order":3,"canonicalText":"白沙雲：「為人多病未足羞，一生無病是吾憂。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-12_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-12","order":4,"canonicalText":"」真確實之論也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-13_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-13","order":1,"canonicalText":"人只一念貪私，便銷剛為柔，塞智為昏，變恩為慘，染潔為污，壞了一生人品。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-13_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-13","order":2,"canonicalText":"故古人以不貪為寶，所以度越一世。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-14_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-14","order":1,"canonicalText":"耳目見聞為外賊，情慾意識為內賊，只是主人公惺惺不昧，獨坐中堂，賊便化為家人矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-15_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-15","order":1,"canonicalText":"圖未就之功，不如保已成之業；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-15_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-15","order":2,"canonicalText":"悔既往之失，亦要防將來之非。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-16_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-16","order":1,"canonicalText":"氣象要高曠，而不可疏狂。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-16_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-16","order":2,"canonicalText":"心思要縝緘，而不可瑣屑。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-16_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-16","order":3,"canonicalText":"趣味要沖淡，而不可偏枯。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-16_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-16","order":4,"canonicalText":"操守要嚴明，而不可激烈。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-17_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-17","order":1,"canonicalText":"風來疏竹，風過而竹不留聲；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-17_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-17","order":2,"canonicalText":"鴈度寒潭，鴈去而潭不留影。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-17_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-17","order":3,"canonicalText":"故君子事來而心始現，事去而心隨空。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-18_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-18","order":1,"canonicalText":"清能有容，仁能善斷，明不傷察，直不過矯，是謂蜜餞不甜、海味不鹹，纔是懿德。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-19_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-19","order":1,"canonicalText":"貧家凈掃地，貧女凈梳頭。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-19_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-19","order":2,"canonicalText":"景色雖不艷麗，氣度自是風雅。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-19_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-19","order":3,"canonicalText":"士君子當窮愁寥落，奈何輒自廢弛哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-20_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-20","order":1,"canonicalText":"閒中不放過，忙中有受用。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-20_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-20","order":2,"canonicalText":"靜中不落空，動中有受用。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-20_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-20","order":3,"canonicalText":"暗中不欺隱，明中有受用。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-21_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-21","order":1,"canonicalText":"念頭起處，纔覺向欲路上去，便挽從理路上來。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-21_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-21","order":2,"canonicalText":"一起便覺，一覺便轉，此是轉禍為福、起死回生的關頭，切莫當面錯過。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-22_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-22","order":1,"canonicalText":"天薄我以福，吾厚吾德以迓之；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-22_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-22","order":2,"canonicalText":"天勞我以形，吾逸吾心以補之；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-22_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-22","order":3,"canonicalText":"天扼我以遇，吾亨吾道以通之。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-22_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-22","order":4,"canonicalText":"天且奈我何哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-23_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-23","order":1,"canonicalText":"真士無心徼福，天即就無心處牖其衷；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-23_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-23","order":2,"canonicalText":"險人著意避禍，天即就著意中奪其魂。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-23_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-23","order":3,"canonicalText":"可見天之機權最神，人之智巧何益！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-24_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-24","order":1,"canonicalText":"聲妓晚景從良，一世之煙花無礙；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-24_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-24","order":2,"canonicalText":"貞婦白頭失守，半生之清苦俱非。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-24_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-24","order":3,"canonicalText":"語雲：「看人只看後半截」，真名言也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-25_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-25","order":1,"canonicalText":"平民肯種德施惠，便是無位的卿相；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-25_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-25","order":2,"canonicalText":"仕夫徒貪權市寵，竟成有爵的乞人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-26_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-26","order":1,"canonicalText":"問祖宗之德澤，吾身所享者是，當念其積累之難；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-26_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-26","order":2,"canonicalText":"問子孫之福祉，吾身所貽者是，要思其傾覆之易。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-27_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-27","order":1,"canonicalText":"君子而詐善，無異小人之肆惡；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-27_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-27","order":2,"canonicalText":"君子而改節，不若小人之自新。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-28_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-28","order":1,"canonicalText":"家人有過不宜暴揚，不宜輕棄。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-28_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-28","order":2,"canonicalText":"此事難言，借他事而隱諷之。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-28_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-28","order":3,"canonicalText":"今日不悟，俟來日正警之。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-28_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-28","order":4,"canonicalText":"如春風之解凍、和氣之消冰，纔是家庭的型範。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-29_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-29","order":1,"canonicalText":"此心常看得圓滿，天下自無缺陷之世界；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-29_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-29","order":2,"canonicalText":"此心常放得寬平，天下自無險側之人情。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-30_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-30","order":1,"canonicalText":"淡薄之士，必為濃艷者所疑；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-30_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-30","order":2,"canonicalText":"檢飭之人，多為放肆者所忌。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-30_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-30","order":3,"canonicalText":"君子處此固不可少變其操履，亦不可太露其鋒芒。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-31_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-31","order":1,"canonicalText":"居逆境中，周身皆鍼砭藥石，砥節礪行而不覺；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-31_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-31","order":2,"canonicalText":"處順境內，滿前盡兵刃戈矛，銷膏糜骨而不知。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-32_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-32","order":1,"canonicalText":"生長富貴叢中的，嗜慾如猛火、權勢似烈焰。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-32_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-32","order":2,"canonicalText":"若不帶些清冷氣味，其火焰不至焚人，必將自焚。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-33_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-33","order":1,"canonicalText":"人心一真，便霜可飛、城可隕、金石可貫。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-33_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-33","order":2,"canonicalText":"若偽妄之人，形骸徒具，真宰已亡。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-33_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-33","order":3,"canonicalText":"對人則面目可憎，獨居則形影自愧。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-34_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-34","order":1,"canonicalText":"文章做到極處，無有他奇，只是恰好；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-34_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-34","order":2,"canonicalText":"人品做到極處，無有他異，只是本然。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-35_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-35","order":1,"canonicalText":"以幻跡言，無論功名富貴，即肢體亦屬委形；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-35_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-35","order":2,"canonicalText":"以真境言，無論父母兄弟，即萬物皆吾一體。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-35_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-35","order":3,"canonicalText":"人能看的破，認的真，纔可以任天下之負擔，亦可脫世間之韁鎖。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-36_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-36","order":1,"canonicalText":"爽口之味，皆爛腸腐骨之藥，五分便無殃；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-36_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-36","order":2,"canonicalText":"快心之事，悉敗身散德之媒，五分便無悔。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-37_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-37","order":1,"canonicalText":"不責人小過，不發人陰私，不念人舊惡，三者可以養德，亦可以遠害。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-38_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-38","order":1,"canonicalText":"天地有萬古，此身不再得；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-38_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-38","order":2,"canonicalText":"人生只百年，此日最易過。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-38_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-38","order":3,"canonicalText":"幸生其間者，不可不知有生之樂，亦不可不懷虛生之憂。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-39_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-39","order":1,"canonicalText":"老來疾病都是壯時招得；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-39_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-39","order":2,"canonicalText":"衰時罪孽都是盛時作得。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-39_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-39","order":3,"canonicalText":"故持盈履滿，君子尤兢兢焉。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-40_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-40","order":1,"canonicalText":"市私恩不如扶公議，結新知不如敦舊好，立榮名不如種陰得，尚奇節不如謹庸行。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-41_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-41","order":1,"canonicalText":"公平正論不可犯手，一犯手則遺羞萬世；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-41_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-41","order":2,"canonicalText":"權門私竇不可著腳，一著腳則玷污終身。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-42_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-42","order":1,"canonicalText":"曲意而使人喜，不若直節而使人忌；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-42_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-42","order":2,"canonicalText":"無善而致人譽，不如無惡而致人毀。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-43_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-43","order":1,"canonicalText":"處父兄骨肉之變，宜從容不宜激烈；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-43_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-43","order":2,"canonicalText":"遇朋友交遊之失，宜剴切不宜優遊。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-44_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-44","order":1,"canonicalText":"小處不滲漏，暗處不欺隱，末路不怠荒，纔是真正英雄。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-45_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-45","order":1,"canonicalText":"驚奇喜異者，終無遠大之識；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-45_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-45","order":2,"canonicalText":"苦節獨行者，要有恆久之操。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-46_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-46","order":1,"canonicalText":"當怒火欲水正騰沸時，明明知得，又明明犯著。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-46_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-46","order":2,"canonicalText":"知得是誰，犯著又是誰。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-46_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-46","order":3,"canonicalText":"此處能猛然轉念，邪魔便為知真君子矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-47_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-47","order":1,"canonicalText":"毋偏信而為奸所欺，毋自任而為氣所使，毋以己之長而形人之短，毋因己之拙而忌人之能。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-48_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-48","order":1,"canonicalText":"人之短處，要曲為彌縫，如暴而揚之，是以短攻短；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-48_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-48","order":2,"canonicalText":"人有頑的，要善為化誨，如忿而嫉之，是以頑濟頑。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-49_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-49","order":1,"canonicalText":"遇沉沉不語之士，且莫輸心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-49_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-49","order":2,"canonicalText":"見悻悻自好之人，應須防口。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-50_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-50","order":1,"canonicalText":"念頭昏散處，要知提醒；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-50_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-50","order":2,"canonicalText":"念頭喫緊時，要知放下。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-50_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-50","order":3,"canonicalText":"不然恐去昏昏之病，又來憧憧之擾矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-51_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-51","order":1,"canonicalText":"霽日青天，倏變為迅雷震電；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-51_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-51","order":2,"canonicalText":"疾風怒雨，倏轉為朗月晴空。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-51_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-51","order":3,"canonicalText":"氣機何嘗一毫凝滯，太虛何嘗一毫障蔽，人之心體亦當如是。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-52_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-52","order":1,"canonicalText":"勝私制欲之功，有曰識不早、力不易者，有曰識得破、忍不過者。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-52_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-52","order":2,"canonicalText":"蓋識是一顆照魔的明珠，力是一把斬魔的慧劍，兩不可少也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-53_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-53","order":1,"canonicalText":"橫逆困窮，是煆煉豪傑的一副爐錘。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-53_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-53","order":2,"canonicalText":"能受其煆煉者，則身心交益；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-53_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-53","order":3,"canonicalText":"不受其煆煉者，則身心交損。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-54_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-54","order":1,"canonicalText":"害人之心不可有，防人之心不可無，此戒疎於慮者。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-54_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-54","order":2,"canonicalText":"寧受人之欺，毋逆人之詐，此警傷於察者。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-54_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-54","order":3,"canonicalText":"二語並存，精明渾厚矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-55_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-55","order":1,"canonicalText":"毋因羣疑而阻獨見，毋任己意而廢人言，毋私小惠而傷大體，毋借公論以快私情。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-56_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-56","order":1,"canonicalText":"善人未能急親，不宜預揚，恐來讒譖之奸；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-56_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-56","order":2,"canonicalText":"惡人未能輕去，不宜先發，恐招媒孽之禍。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-57_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-57","order":1,"canonicalText":"青天白日的節義，自暗室屋漏中培來；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-57_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-57","order":2,"canonicalText":"旋乾轉坤的經綸，從臨深履薄中操出。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-58_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-58","order":1,"canonicalText":"父慈子孝、兄友弟恭，縱做到極處，俱是合當如是，著不得一毫感激的念頭。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-58_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-58","order":2,"canonicalText":"如施者任德，受者懷恩，便是路人，便成市道矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-59_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-59","order":1,"canonicalText":"炎涼之態，富貴更甚於貧賤；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-59_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-59","order":2,"canonicalText":"妒忌之心，骨肉尤狠於外人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-59_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-59","order":3,"canonicalText":"此處若不當以冷腸，御以平氣，鮮不日坐煩惱障中矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-60_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-60","order":1,"canonicalText":"功過不宜少混，混則人懷惰隳之心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-60_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-60","order":2,"canonicalText":"恩仇不可太明，明則人起攜貳之志。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-61_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-61","order":1,"canonicalText":"惡忌陰，善忌陽，故惡之顯者禍淺，而隱者禍深。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-61_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-61","order":2,"canonicalText":"善之顯者功小，而隱者功大。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-62_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-62","order":1,"canonicalText":"德者才之主，才者德之奴；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-62_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-62","order":2,"canonicalText":"有才無德如家無主，而奴用事矣，幾何不魍魎猖狂。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-63_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-63","order":1,"canonicalText":"鋤奸杜倖，要放他一條去路。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-63_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-63","order":2,"canonicalText":"若使之一無所容，便如塞鼠穴者，一切去路都塞盡，則一切好物都咬破矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-64_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-64","order":1,"canonicalText":"士君子貧不能濟物者，遇人癡迷處，出一言提醒之，遇人急難處，出一言解救之，亦是無量功德矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-65_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-65","order":1,"canonicalText":"處己者觸事皆成藥石，尤人者動念即是戈矛，一以闢眾善之路，一以濬諸惡之源，相去霄壤矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-66_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-66","order":1,"canonicalText":"事業文章隨身銷毀，而精神萬古如新；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-66_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-66","order":2,"canonicalText":"功名富貴逐世轉移，而氣節千載一時。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-66_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-66","order":3,"canonicalText":"羣信不以彼易此也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-67_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-67","order":1,"canonicalText":"魚網之設，鴻則罹其中；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-67_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-67","order":2,"canonicalText":"螳螂之貪，雀又乘其後。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-67_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-67","order":3,"canonicalText":"機裏藏機變外生變，智巧何足恃哉。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-68_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-68","order":1,"canonicalText":"作人無一點真懇的念頭，便成個花子，事事皆虛；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-68_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-68","order":2,"canonicalText":"涉世無一段圓活的機趣，便是個木人，處處有礙。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-69_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-69","order":1,"canonicalText":"有一念而犯鬼神之忌，一言而傷天地之和，一事而釀子孫之禍者，最宜切戒。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-70_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-70","order":1,"canonicalText":"事有急之不白者，寬之或自明，毋躁急以速其忿；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-70_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-70","order":2,"canonicalText":"人有切之不從者，縱之或自化，毋操切以益其頑。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-71_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-71","order":1,"canonicalText":"節義傲青雲，文章高白雪，若不以德性陶鎔之，終為血氣之私、技能之末。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-72_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-72","order":1,"canonicalText":"謝事當謝於正盛之時，居身宜居於獨後之地，謹德須謹於至微之事，施恩務施於不報之人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-73_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-73","order":1,"canonicalText":"德者事業之基，未有基不固而棟宇堅久者；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-4_p-73_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-4","passageId":"cai-gen-tan_ch-4_p-73","order":2,"canonicalText":"心者修裔之根，未有根不植而枝葉榮茂者。","chunks":[],"tags":[]}]}');export{a as default};
